/* MathQuest — Physique-chimie 6e et 5e (collège) : 22 chapitres reconstruits, année scolaire 2026-2027.
   Programme(s) appliqué(s) :
   - 6e : programme de sciences et technologie du cycle 3, annexe de l’arrêté du 15 juin 2023 (NOR MENE2314101A) publiée au BO n°25 du 22 juin 2023,
     thème « Matière, mouvement, énergie, information ». Le nouveau programme de cycle 3 (arrêté du 5 juin 2026, NOR MENE2611650A, BO n°24 du 11 juin 2026)
     ne s’applique en 6e qu’à la rentrée 2027 (article 3 de l’arrêté) : il n’est donc pas utilisé ici.
   - 5e : programme de physique-chimie du cycle 4, arrêté du 9 novembre 2015 modifié, version consolidée publiée au BO n°31 du 30 juillet 2020.
     Le projet de nouveau programme de cycle 4 (CSP, juillet 2025 ; consultation du 18 mai au 19 juin 2026) n’a pas fait l’objet d’un arrêté applicable en 5e en 2026-2027.
   Vérifié le 7 octobre 2026 sur legifrance.gouv.fr (JORFTEXT000054218988), education.gouv.fr (BO n°25 du 22 juin 2023, annexe) et eduscol.education.gouv.fr (programme du cycle 4 en vigueur à la rentrée 2020). */
(function(){
'use strict';
const MQ=window.MQCollege;if(!MQ)return;const H=MQ.H;
const {R,P,ch,num,order,bank,pairs,sort,seq,mix,pickN,shuffle,nf,dec}=H;
const C=(d,u,ex,m,a,r)=>({d,u,ex,m,a,r});const T=(t,h)=>({t,h});
const REF6='Cycle 3 — programme de sciences et technologie, arrêté du 15 juin 2023, BO n°25 du 22 juin 2023 (programme applicable en 6e en 2026-2027)';
const REF5='Cycle 4 — programme de physique-chimie, arrêté du 9 novembre 2015 modifié, version consolidée au BO n°31 du 30 juillet 2020 (applicable en 5e en 2026-2027)';
const T6=s=>`BO n°25 du 22 juin 2023 — thème « Matière, mouvement, énergie, information », partie « ${s} »`;
const T5=s=>`BO n°31 du 30 juillet 2020 — physique-chimie cycle 4, ${s}`;

/* ===== Outils communs ===== */
const rd=(x,k=6)=>Math.round(x*10**k)/10**k;
const F=x=>dec(x,6);
const V0=/^[aeiouyéèêâîôh]/i;const de=n=>V0.test(n)?'d’'+n:'de '+n;const artM=n=>V0.test(n)?'l’'+n:'le '+n;const duM=n=>V0.test(n)?'de l’'+n:'du '+n;
const du=n=>/^le /.test(n)?'du '+n.slice(3):/^les /.test(n)?'des '+n.slice(4):'de '+n;const au=n=>/^le /.test(n)?'au '+n.slice(3):/^les /.test(n)?'aux '+n.slice(4):'à '+n;
const SUB='₀₁₂₃₄₅₆₇₈₉';const sub=n=>n===1?'':String(n).split('').map(c=>SUB[+c]).join('');

/* Conversions d'unités (facteur exprimé dans l'unité de base : mL ou g). */
const VOL=[['m³',1e6],['L',1000],['dm³',1000],['dL',100],['cL',10],['mL',1],['cm³',1]];
const MAS=[['t',1e6],['kg',1000],['g',1],['mg',0.001]];
function conv(list,d,kind){
  let a,b,v,res,ratio;
  for(let k=0;k<40;k++){
    [a,b]=pickN(list,2);ratio=rd(a[1]/b[1],9);
    const lim=d===1?1000:d===2?1e4:1e6;if(ratio>lim||ratio<1/lim)continue;
    v=d===1?P([R(1,20),R(2,9)*10,R(1,9)*100]):d===2?P([R(1,999),R(1,99)/10,R(11,99)]):P([R(1,9999)/100,R(1,999)/10,R(1,999)]);v=rd(v);
    res=rd(v*ratio);const decs=(String(res).split('.')[1]||'').length;
    if(res>=0.001&&res<=1e7&&decs<=4)break;
  }
  const up=ratio>=1,f=up?ratio:rd(1/ratio);
  const expl=ratio===1?`1 ${a[0]} = 1 ${b[0]} : la valeur ne change pas. ${F(v)} ${a[0]} = <b>${F(res)} ${b[0]}</b>.`:
    up?`1 ${a[0]} = ${F(f)} ${b[0]} : on passe à une unité plus petite, on <b>multiplie</b> par ${F(f)}. ${F(v)} × ${F(f)} = <b>${F(res)} ${b[0]}</b>.`:
       `1 ${b[0]} = ${F(f)} ${a[0]} : on passe à une unité plus grande, on <b>divise</b> par ${F(f)}. ${F(v)} ÷ ${F(f)} = <b>${F(res)} ${b[0]}</b>.`;
  const hint=kind==='vol'?'1 L = 1 000 mL = 1 dm³ et 1 mL = 1 cm³.':'1 kg = 1 000 g ; 1 g = 1 000 mg ; 1 t = 1 000 kg.';
  if(Math.random()<.5)return num(`Convertis <b>${F(v)} ${a[0]}</b> en <b>${b[0]}</b>.`,res,{unit:b[0],expl,hint});
  const bad=[rd(v/ratio),rd(res*10),rd(res/10),rd(res*100),rd(res/1000)].filter(x=>x>0&&x<1e9).map(x=>F(x)+' '+b[0]);
  return ch(`${F(v)} ${a[0]} = … ${b[0]}`,F(res)+' '+b[0],bad,{expl,hint});
}

/* Courbe température-temps (SVG décoratif + relevés écrits : le texte suffit pour répondre). */
function plot(pts){
  const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]);const xm=Math.max(...xs);
  let lo=Math.min(...ys),hi=Math.max(...ys);const st=(hi-lo)>160?80:(hi-lo)>80?40:(hi-lo)>40?20:(hi-lo)>16?10:5;
  lo=Math.floor(lo/st)*st;hi=Math.ceil(hi/st)*st;if(hi===lo)hi=lo+st;
  const X=x=>(46+x/xm*236).toFixed(1),Y=y=>(160-(y-lo)/(hi-lo)*140).toFixed(1);
  let s=`<line x1="46" y1="160" x2="286" y2="160" class="ln"/><line x1="46" y1="160" x2="46" y2="14" class="ln"/>`;
  for(let v=lo;v<=hi;v+=st)s+=`<line x1="42" y1="${Y(v)}" x2="286" y2="${Y(v)}" stroke="currentColor" stroke-opacity=".15"/><text x="38" y="${(+Y(v)+4).toFixed(1)}" text-anchor="end" class="tk">${nf(v)}</text>`;
  const sx=xm>12?2:1;for(let t=0;t<=xm;t+=sx)s+=`<text x="${X(t)}" y="177" text-anchor="middle" class="tk">${t}</text>`;
  s+=`<polyline points="${pts.map(p=>X(p[0])+','+Y(p[1])).join(' ')}" class="ac"/>`+pts.map(p=>`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="3" class="dot"/>`).join('');
  s+=`<text x="284" y="152" text-anchor="end" class="tk">t (min)</text><text x="52" y="12" class="tk">θ (°C)</text>`;
  return `<svg class="fig pfig" viewBox="0 0 300 184" role="img" aria-label="Courbe de la température en fonction du temps">${s}</svg>`;
}
const releves=pts=>`<br><small>Relevés : ${pts.map(p=>`${p[0]} min → ${nf(p[1])} °C`).join(' ; ')}</small>`;
const SUBST=[{n:'de l’eau',tf:0,lab:'eau'},{n:'de l’acide stéarique',tf:69,lab:'acide stéarique'},{n:'de l’étain',tf:232,lab:'étain'},{n:'du plomb',tf:327,lab:'plomb'}];
function curveQ(d,lvl){
  const heat=Math.random()<.5;const pure=!(d===3&&Math.random()<.35);
  const sb=d===1?SUBST[0]:P(d===2?SUBST.slice(0,2):SUBST);const tp=sb.tf;
  const s1=P([2,4,5]),n1=R(2,4),n2=R(2,5),s3=P([2,4,5]),n3=R(2,3);const dir=heat?1:-1;
  const pts=[];let th=tp-dir*s1*n1,t=0;pts.push([t,th]);
  if(pure){for(let i=0;i<n1;i++){th+=dir*s1;pts.push([++t,th]);}for(let i=0;i<n2;i++)pts.push([++t,th]);for(let i=0;i<n3;i++){th+=dir*s3;pts.push([++t,th]);}}
  else{th=10;pts.length=0;pts.push([0,th]);for(const s of [3,3,3,3,1,1,1,1,3,3]){th-=s;pts.push([++t,th]);}}
  const fig=plot(pts)+releves(pts);
  const who=pure?(d===3?'un corps pur inconnu':sb.n):'de l’eau salée';
  const intro=pure?`On ${heat?'chauffe':'laisse refroidir'} ${who}${heat?' initialement solide':' initialement liquide'} et on relève sa température chaque minute.`:`On refroidit ${who} initialement liquide et on relève sa température chaque minute.`;
  if(!pure)return ch(`${intro}${fig}<br>D’après la courbe, ce liquide est-il un corps pur ?`,'Non, car il n’y a pas de palier : la température continue de baisser pendant la solidification',['Oui, car la température baisse régulièrement','Oui, car la courbe commence à 10 °C','On ne peut rien dire sans connaître sa masse'],{expl:'Un corps pur change d’état à température constante (palier). Ici, la température baisse seulement plus lentement entre 1 °C et −2 °C mais ne reste jamais constante : c’est un mélange (eau + sel).',hint:'Cherche un palier horizontal.'});
  const t1=n1,t2=n1+n2;const name=heat?'fusion':'solidification';
  const r=Math.random();
  if(d===3&&r<.4){const others=SUBST.filter(x=>x!==sb);return ch(`${intro}${fig}<br>Températures de fusion : eau 0 °C ; acide stéarique 69 °C ; étain 232 °C ; plomb 327 °C. Quel est ce corps pur ?`,sb.lab,others.map(x=>x.lab),{expl:`Le palier a lieu à ${nf(tp)} °C : c’est la température de ${name} du corps pur, qui est la même que sa température de fusion. On reconnaît <b>${sb.lab}</b>.`,hint:'Repère la température du palier.'});}
  if(r<.35)return num(`${intro}${fig}<br>À quelle température a lieu le palier ?`,tp,{unit:'°C',expl:`La température reste constante à <b>${nf(tp)} °C</b> de t = ${t1} min à t = ${t2} min : c’est le palier de ${name}.`,hint:'Cherche la partie horizontale de la courbe.'});
  if(r<.55)return num(`${intro}${fig}<br>Pendant combien de minutes la température reste-t-elle constante ?`,n2,{unit:'min',expl:`Le palier commence à t = ${t1} min et finit à t = ${t2} min : ${t2} − ${t1} = <b>${n2} min</b>.`,hint:'Durée = instant de fin − instant de début.'});
  if(r<.75){const k=R(0,pts.length-1);return num(`${intro}${fig}<br>Quelle température indique le thermomètre à t = ${k} min ?`,pts[k][1],{unit:'°C',expl:`On lit le point d’abscisse ${k} min : son ordonnée est <b>${nf(pts[k][1])} °C</b>.`,hint:'Pars de l’axe du temps, monte jusqu’à la courbe, puis lis la température.'});}
  return ch(`${intro}${fig}<br>Que se passe-t-il pendant le palier ?`,heat?'la fusion : le solide devient liquide':'la solidification : le liquide devient solide',[heat?'la solidification : le liquide devient solide':'la fusion : le solide devient liquide','la vaporisation : le liquide devient gaz','rien : le chauffage est arrêté'],{expl:`Pendant le palier, ${heat?'le corps reçoit de l’énergie mais sa température ne monte pas : il fond (fusion)':'le corps cède de l’énergie mais sa température ne baisse pas : il se solidifie'}. Solide et liquide coexistent.`,hint:'Le corps est solide au début ?'});
}

/* Masse volumique (valeurs de référence, g/cm³). */
const MET=[['aluminium',2.7],['titane',4.51],['zinc',7.14],['fer',7.87],['cuivre',8.96],['argent',10.5],['plomb',11.35],['or',19.3]];
const LIQ=[['éthanol',0.79],['huile de tournesol',0.92],['eau',1],['glycérol',1.26]];
const tableMet=()=>MET.map(m=>`${m[0]} ${F(m[1])}`).join(' ; ');

/* Vitesse */
const MOV=[['Un coureur',[3,4,5,6,8]],['Un cycliste',[5,6,8,10,12]],['Un cheval au galop',[10,12,15]],['Une trottinette électrique',[4,5,6]],['Un nageur',[1,2]]];
function vit6(d){
  const r=Math.random();
  if(d===1||r<.3){const [who,vs]=P(MOV);const v=P(vs),t=P([5,8,10,12,15,20,25,30,40,50,60]);const D=v*t;
    if(Math.random()<.5)return num(`${who} parcourt <b>${nf(D)} m</b> en <b>${t} s</b> à vitesse constante. Quelle est la valeur de sa vitesse ?`,v,{unit:'m/s',expl:`v = d ÷ t = ${nf(D)} m ÷ ${t} s = <b>${v} m/s</b>.`,hint:'Vitesse = distance ÷ durée.'});
    return ch(`${who} parcourt <b>${nf(D)} m</b> en <b>${t} s</b> à vitesse constante. Quelle est la valeur de sa vitesse ?`,`${v} m/s`,[`${nf(D*t)} m/s`,`${v} km/h`,`${dec(t/D,3)} m/s`,`${nf(D-t)} m/s`],{expl:`On divise la distance par la durée (et non l’inverse) : v = ${nf(D)} ÷ ${t} = <b>${v} m/s</b>. L’unité vient des unités utilisées : mètres et secondes donnent des m/s.`,hint:'v = d ÷ t.'});}
  if(r<.5){const v=P([5,8,10,12,15,20]),t=P([5,10,20,30]);const D=v*t;return num(`Un robot programmable parcourt <b>${D} cm</b> en <b>${t} s</b> en ligne droite à vitesse constante. Quelle est sa vitesse en cm/s ?`,v,{unit:'cm/s',expl:`v = ${D} cm ÷ ${t} s = <b>${v} cm/s</b>.`,hint:'Distance ÷ durée.'});}
  if(r<.75||d===2){const v=P([30,40,50,60,70,80,90,100,110,120,130]),t=P([2,3,4]);const D=v*t;
    return ch(`Une voiture parcourt <b>${D} km</b> en <b>${t} h</b> sur l’autoroute, à vitesse constante. Sa vitesse est…`,`${v} km/h`,[`${nf(D*t)} km/h`,`${v} m/s`,`${D} km/h`,`${dec(t/D,3)} km/h`],{expl:`v = d ÷ t = ${D} km ÷ ${t} h = <b>${v} km/h</b>.`,hint:'Kilomètres et heures donnent des km/h.'});}
  // d=3 : durée en minutes, à convertir
  let v,t,D;for(let k=0;k<30;k++){v=P([12,15,18,20,24,30,36,40,45,60,90]);t=P([10,15,20,30,40,45]);D=v*t/60;if(Number.isInteger(D))break;}
  if(!Number.isInteger(D)){v=60;t=30;D=30;}const who=v<=24?'Un cycliste':v<=45?'Un scooter':'Une voiture';
  return num(`${who} parcourt <b>${D} km</b> en <b>${t} min</b> à vitesse constante. Quelle est sa vitesse en km/h ?`,v,{unit:'km/h',expl:`${t} min = ${t} ÷ 60 h. v = d ÷ t = ${D} ÷ (${t} ÷ 60) = ${D} × 60 ÷ ${t} = <b>${v} km/h</b> : c’est la distance qui serait parcourue en 60 min.`,hint:'Combien de fois la durée tient-elle dans 1 h = 60 min ?'});
}
function vit5(d){
  const r=Math.random();
  if(r<.25)return vit6(d);
  if(r<.45){// conversion m/s <-> km/h
    const v=R(2,d===1?10:40),k=rd(v*3.6);
    if(Math.random()<.5)return num(`Convertis <b>${v} m/s</b> en km/h.`,k,{unit:'km/h',expl:`En 1 s : ${v} m ; en 1 h = 3 600 s : ${v} × 3 600 = ${nf(v*3600)} m = ${F(k)} km. Donc ${v} m/s = <b>${F(k)} km/h</b> (on multiplie par 3,6).`,hint:'De m/s vers km/h : × 3,6.'});
    return ch(`<b>${F(k)} km/h</b> = … m/s`,`${v} m/s`,[`${F(rd(k*3.6))} m/s`,`${F(rd(k*1000))} m/s`,`${F(rd(k/60))} m/s`],{expl:`De km/h vers m/s, on divise par 3,6 : ${F(k)} ÷ 3,6 = <b>${v} m/s</b>.`,hint:'De km/h vers m/s : ÷ 3,6.'});}
  if(r<.6){// d = v × t
    const v=P([5,8,10,12,15,20,25]),t=P([30,40,60,90,120,150]);return num(`Un objet se déplace à <b>${v} m/s</b> pendant <b>${t} s</b> (mouvement uniforme). Quelle distance parcourt-il ?`,v*t,{unit:'m',expl:`d = v × t = ${v} × ${t} = <b>${nf(v*t)} m</b>.`,hint:'Distance = vitesse × durée.'});}
  if(r<.75&&d>=2){// t = d / v
    const v=P([50,60,80,90,100,120,130]),t=P([0.5,1.5,2,2.5,3]);const D=v*t;return num(`Un car roule à <b>${v} km/h</b> de moyenne. Combien d’heures lui faut-il pour parcourir <b>${F(D)} km</b> ?`,t,{unit:'h',expl:`t = d ÷ v = ${F(D)} ÷ ${v} = <b>${F(t)} h</b>${t%1?` (soit ${Math.floor(t)} h 30 min)`:''}.`,hint:'Durée = distance ÷ vitesse.'});}
  // comparer deux vitesses dans des unités différentes
  let a,b;for(let k=0;k<20;k++){a=R(5,40);b=P([20,30,50,60,70,80,90,100,110,120]);if(Math.abs(a*3.6-b)>2)break;}
  const ka=rd(a*3.6);const AN=P([['Un guépard','une voiture'],['Un cheval','un scooter'],['Un sprinteur','un vélo électrique'],['Une hirondelle','un train régional']]);
  const g=ka>b?`${AN[0].toLowerCase()} (${a} m/s)`:`${AN[1]} (${b} km/h)`;
  return ch(`Qui va le plus vite : ${AN[0].toLowerCase()} à <b>${a} m/s</b> ou ${AN[1]} à <b>${b} km/h</b> ?`,g,[ka>b?`${AN[1]} (${b} km/h)`:`${AN[0].toLowerCase()} (${a} m/s)`,'ils vont à la même vitesse','on ne peut pas comparer des unités différentes'],{expl:`On convertit dans la même unité : ${a} m/s × 3,6 = ${F(ka)} km/h, à comparer à ${b} km/h. Le plus rapide est donc ${g}.`,hint:'Convertis d’abord dans la même unité.'});
}

/* Son et lumière */
function thunder(d){
  const t=d===1?R(1,5):R(2,15);const D=340*t;
  if(d===3&&Math.random()<.5)return ch(`Tu entends le tonnerre <b>${t} s</b> après avoir vu l’éclair. Le son se propage dans l’air à environ 340 m/s. À quelle distance est tombé l’éclair ?`,`environ ${F(rd(D/1000,3))} km`,[`environ ${nf(D)} km`,`environ ${F(rd(340/t,2))} m`,`environ ${F(rd(D/100,3))} km`],{expl:`d = v × t = 340 × ${t} = ${nf(D)} m = <b>${F(rd(D/1000,3))} km</b>. La lumière de l’éclair arrive presque instantanément.`,hint:'d = v × t, puis convertis en km.'});
  return num(`Tu vois un éclair et tu entends le tonnerre <b>${t} s</b> plus tard. Le son se propage dans l’air à environ 340 m/s. À quelle distance (en mètres) est tombé l’éclair ?`,D,{unit:'m',expl:`La lumière arrive presque instantanément ; le son met ${t} s. d = v × t = 340 × ${t} = <b>${nf(D)} m</b>.`,hint:'Distance = vitesse × durée.'});
}

/* ===================== 6e ===================== */
MQ.add('pc','6',[
{id:'pc6a',name:'États de la matière et changements d’état',icon:'🧊',domain:'Matière',
 refs:[REF6,T6('États et constitution de la matière à l’échelle macroscopique')],
 tip:'Pour nommer un changement d’état, écris « état de départ → état d’arrivée » : solide → liquide, c’est la fusion ; liquide → gaz, la vaporisation.',
 c:C(`Un glaçon oublié sur la table devient une flaque, puis la flaque finit par disparaître. L’eau s’est-elle volatilisée ? Pas du tout : elle a changé d’<b>état</b>. Comment décrire les états de la matière et nommer leurs changements ?`,
  [T('Trois états physiques',`<p>Un <b>solide</b> a une forme propre et un volume propre (un caillou, un glaçon). Un <b>liquide</b> a un volume propre mais pas de forme propre : il prend la forme du récipient et, au repos, sa surface libre est plane et horizontale. Un <b>gaz</b> n’a ni forme propre ni volume propre : il occupe tout l’espace disponible et on peut le comprimer.</p><p>Le sable ou le sucre en poudre « coulent » mais chaque grain est un solide. Dans la nature, l’eau existe sous les trois états : glace, neige, grêle (solide) ; océans, rivières, pluie (liquide) ; vapeur d’eau dans l’air (gaz <b>invisible</b>). La buée et les nuages sont faits de fines gouttelettes d’eau <b>liquide</b>.</p>`),
   T('Nommer les changements d’état',`<table class="ptable"><tr><th>Passage</th><th>Nom</th></tr><tr><td>solide → liquide</td><td>fusion</td></tr><tr><td>liquide → solide</td><td>solidification</td></tr><tr><td>liquide → gaz</td><td>vaporisation (évaporation lente ou ébullition)</td></tr><tr><td>gaz → liquide</td><td>liquéfaction (on dit aussi condensation liquide)</td></tr><tr><td>solide → gaz</td><td>sublimation</td></tr><tr><td>gaz → solide</td><td>condensation solide</td></tr></table><p>Ces changements sont <b>réversibles</b> : de la glace fondue peut être congelée de nouveau.</p>`),
   T('Températures de changement d’état, masse et volume',`<p>Sous la pression atmosphérique normale, l’eau pure <b>fond à 0 °C</b> (et se solidifie à 0 °C) et <b>bout à 100 °C</b>. En dessous de 0 °C, l’eau pure est solide ; entre 0 °C et 100 °C, elle est liquide ; au-dessus de 100 °C, elle est gazeuse.</p><p>Lors d’un changement d’état, la <b>masse se conserve</b> : 50 g de glace donnent 50 g d’eau liquide. En revanche, le <b>volume change</b> : l’eau qui gèle augmente de volume d’environ 9 % (une bouteille pleine éclate au congélateur).</p>`)],
  [{q:'Un glaçon de 25 g fond complètement dans un verre. Quelle est la masse d’eau liquide obtenue ?',s:['Le glaçon passe de l’état solide à l’état liquide : c’est une fusion.','Lors d’un changement d’état, la masse se conserve.','On obtient donc 25 g d’eau liquide (le volume, lui, diminue un peu).']},
   {q:'Quel est l’état de l’eau pure à −8 °C, à 37 °C et à 120 °C (pression normale) ?',s:['−8 °C est inférieur à 0 °C : glace, état solide.','37 °C est compris entre 0 °C et 100 °C : état liquide.','120 °C est supérieur à 100 °C : vapeur d’eau, état gazeux.']}],
  ['J’identifie l’état de départ et l’état d’arrivée.','Je nomme le changement grâce au tableau (fusion, solidification, vaporisation, liquéfaction, sublimation, condensation solide).','Pour l’eau, je compare la température à 0 °C et à 100 °C.','Je me rappelle que la masse se conserve, pas le volume.'],
  ['Croire que la buée ou les nuages sont de la vapeur d’eau : ce sont des gouttelettes d’eau liquide, la vapeur est invisible.','Confondre fusion et dissolution : le sucre qui disparaît dans l’eau se dissout, il ne fond pas.','Penser que la masse change quand l’eau gèle : seul le volume change.'],
  ['Solide : forme et volume propres ; liquide : volume propre ; gaz : ni forme ni volume propres.','Fusion, solidification, vaporisation, liquéfaction, sublimation, condensation solide.','Eau pure : fusion à 0 °C, ébullition à 100 °C ; la masse se conserve lors d’un changement d’état.']),
 g:mix([d=>{let th;do{th=d===1?P([R(-30,-2),R(5,95),R(105,150)]):R(-40,150);}while(th===0||th===100);
    const st=th<0?'solide (glace)':th<100?'liquide':'gazeux (vapeur d’eau)';
    return ch(`Sous la pression atmosphérique normale, dans quel état se trouve de l’eau pure à <b>${nf(th)} °C</b> ?`,st,['solide (glace)','liquide','gazeux (vapeur d’eau)','un mélange de glace et de vapeur'].filter(x=>x!==st),{expl:`L’eau pure fond à 0 °C et bout à 100 °C. ${nf(th)} °C est ${th<0?'inférieur à 0 °C : <b>solide</b>':th<100?'compris entre 0 °C et 100 °C : <b>liquide</b>':'supérieur à 100 °C : <b>gaz</b>'}.`,hint:'Compare avec 0 °C et 100 °C.'});},3],
  [sort({'fusion':['un glaçon qui devient de l’eau liquide','du chocolat qui fond au soleil','la neige qui fond au printemps','du beurre chauffé dans une poêle'],'solidification':['de l’eau qui gèle dans le congélateur','la lave qui refroidit et durcit','du chocolat fondu qui durcit au réfrigérateur','la cire fondue qui durcit en refroidissant'],'vaporisation':['une flaque d’eau qui disparaît au soleil','le linge mouillé qui sèche','de l’eau qui bout dans une casserole','l’eau de mer qui s’évapore dans un marais salant'],'liquéfaction':['la buée qui se forme sur le miroir de la salle de bain','des gouttelettes sur une canette sortie du réfrigérateur','la rosée du matin sur l’herbe'],'sublimation':['la neige carbonique (dioxyde de carbone solide) qui disparaît sans fondre','de la neige qui disparaît sans fondre par grand froid sec'],'condensation solide':['le givre qui se forme sur une vitre en hiver','le givre qui se dépose dans un congélateur souvent ouvert']},{q:'Quel changement d’état observe-t-on : %s ?',e:(x,c)=>`« ${x} » : c’est une ${c}. Fusion : solide → liquide ; solidification : liquide → solide ; vaporisation : liquide → gaz ; liquéfaction : gaz → liquide ; sublimation : solide → gaz ; condensation solide : gaz → solide.`}),3],
  [d=>{const m=d===1?R(2,30)*5:R(11,999);const k=P(['Un glaçon','Un bloc de glace','Un bac de glaçons']);const g=m>=1000?'kg':'g';
    return num(`${k} de <b>${nf(m)} g</b> fond complètement dans un récipient fermé. Quelle est la masse d’eau liquide obtenue ?`,m,{unit:'g',expl:`Lors d’un changement d’état, la masse se conserve : on obtient <b>${nf(m)} g</b> d’eau liquide. Seul le volume change.`,hint:'Que devient la masse lors d’une fusion ?'});},1],
  [d=>{const S=[['l’éthanol (alcool)',-114,78],['le mercure',-39,357],['le plomb',327,1749],['l’aluminium',660,2519]];const [n,f,e]=P(S);
    const pool=[R(f-60,f-5),R(f+5,e-5),R(e+5,e+60)];let th=P(pool);if(th===f||th===e)th+=1;
    const st=th<f?'solide':th<e?'liquide':'gazeux';
    return ch(`${n.charAt(0).toUpperCase()+n.slice(1)} fond à ${nf(f)} °C et bout à ${nf(e)} °C (pression normale). Dans quel état est-il à <b>${nf(th)} °C</b> ?`,st,['solide','liquide','gazeux'].filter(x=>x!==st),{expl:`En dessous de ${nf(f)} °C : solide ; entre ${nf(f)} °C et ${nf(e)} °C : liquide ; au-dessus de ${nf(e)} °C : gaz. À ${nf(th)} °C, il est <b>${st}</b>.`,hint:'Place la température sur une droite graduée avec les deux températures de changement d’état.'});},2],
  [bank([['Quel état de la matière a une forme propre et un volume propre ?','le solide',['le liquide','le gaz','aucun'],'Un solide garde sa forme et son volume, quel que soit le récipient.'],
   ['Quel état n’a ni forme propre ni volume propre ?','le gaz',['le liquide','le solide','la poudre'],'Un gaz occupe tout le volume disponible et se comprime.'],
   ['Le sucre en poudre prend la forme du bol. Il est…','solide (chaque grain a sa forme)',['liquide','gazeux','ni solide ni liquide'],'Une poudre est formée de petits grains solides : c’est l’ensemble des grains qui épouse la forme du récipient.',2],
   ['La buée sur une vitre est formée…','de gouttelettes d’eau liquide',['de vapeur d’eau','de glace','d’air chaud'],'La vapeur d’eau est invisible ; au contact de la vitre froide, elle se liquéfie en gouttelettes.',2],
   ['Une bouteille d’eau pleine et fermée éclate au congélateur, car…','l’eau augmente de volume en gelant',['l’eau augmente de masse en gelant','la glace est plus lourde que l’eau','le froid attire l’air'],'La masse ne change pas, mais le volume de la glace est environ 9 % plus grand.',3],
   ['Le sucre qui disparaît dans le thé…','se dissout',['fond','se vaporise','se sublime'],'Le sucre ne devient pas liquide par chauffage : il se mélange à l’eau, c’est une dissolution.',2],
   {n:'À quelle température (en °C) l’eau pure bout-elle sous la pression atmosphérique normale ?',a:100,u:'°C',e:'L’ébullition de l’eau pure a lieu à 100 °C sous la pression normale.'},
   {n:'À quelle température (en °C) la glace pure fond-elle sous la pression atmosphérique normale ?',a:0,u:'°C',e:'La fusion de la glace pure a lieu à 0 °C ; sa solidification aussi.'},
   ['Au repos, la surface libre d’un liquide est…','plane et horizontale',['toujours inclinée','bombée vers le haut','verticale'],'Même si on penche le verre, la surface de l’eau au repos reste horizontale.',2]]),2])},

{id:'pc6b',name:'Mélanges, solutions et séparation',icon:'🧪',domain:'Matière',
 refs:[REF6,T6('États et constitution de la matière à l’échelle macroscopique — Mélanges')],
 tip:'Avant de choisir une technique de séparation, demande-toi : les constituants sont-ils visibles (hétérogène) ou non (homogène) ? Solide ou liquide ?',
 c:C(`L’eau de mer est salée, l’eau boueuse est trouble, la vinaigrette se sépare en deux couches. Ce sont des <b>mélanges</b>. Comment les reconnaître et comment récupérer chacun de leurs constituants ?`,
  [T('Mélanges homogènes et hétérogènes',`<p>Un mélange est <b>hétérogène</b> si l’on distingue à l’œil nu au moins deux constituants (eau boueuse, eau + huile, sable + cailloux). Il est <b>homogène</b> si l’on ne distingue qu’une seule phase (eau salée, sirop, air).</p><p>Quand un solide se <b>dissout</b> dans un liquide, on obtient une <b>solution</b> : le solide est le <b>soluté</b>, le liquide est le <b>solvant</b>. La masse totale se conserve : 200 g d’eau + 10 g de sel donnent 210 g d’eau salée. On ne peut pas dissoudre une quantité illimitée : à 20 °C, environ 36 g de sel au maximum dans 100 g d’eau (environ 100 mL). Au-delà, le sel ne se dissout plus et se dépose : la solution est <b>saturée</b>.</p>`),
   T('Séparer les constituants',`<ul class="lst"><li><b>Tamisage</b> : séparer des solides de tailles différentes (sable et cailloux).</li><li><b>Décantation</b> : laisser reposer ; le solide tombe au fond. Deux liquides <b>non miscibles</b> (eau et huile) se séparent en deux couches et on les récupère avec une <b>ampoule à décanter</b>. Le liquide qui a la plus grande masse pour un même volume (l’eau) est en dessous.</li><li><b>Filtration</b> : le filtre retient les particules solides ; le liquide limpide obtenu est le <b>filtrat</b>.</li><li><b>Évaporation</b> : on récupère un solide dissous (sel des marais salants).</li></ul>`),
   T('L’air, un mélange de gaz ; mélanges et sécurité',`<p>L’air est un mélange homogène : environ <b>78 % de diazote</b>, <b>21 % de dioxygène</b> et 1 % d’autres gaz (argon, dioxyde de carbone…). Le dioxyde de carbone, le méthane, la vapeur d’eau et le protoxyde d’azote sont des <b>gaz à effet de serre</b>.</p><p>Certains mélanges provoquent une <b>transformation chimique</b> : vinaigre + bicarbonate de soude produit un gaz (effervescence). Les produits ménagers portent des <b>pictogrammes</b> de danger (corrosif, inflammable, toxique…) : on ne les mélange jamais.</p>`)],
  [{q:'Comment récupérer de l’eau limpide et le sel à partir d’eau de mer boueuse ?',s:['Je laisse reposer : la terre tombe au fond (décantation).','Je filtre : le filtre retient les dernières particules de terre, le filtrat est limpide mais salé.','Je fais évaporer l’eau du filtrat : le sel reste au fond du récipient.']},
   {q:'On dissout 15 g de sel dans 250 g d’eau. Quelle est la masse de la solution ?',s:['Lors d’une dissolution, la masse totale se conserve.','m(solution) = m(eau) + m(sel) = 250 g + 15 g.','La solution a une masse de 265 g.']}],
  ['Je regarde si le mélange est homogène ou hétérogène.','Je repère la nature des constituants (solide, liquide, dissous ou non).','Je choisis la technique : tamisage, décantation, filtration ou évaporation.','J’applique la conservation de la masse lors d’un mélange.'],
  ['Croire que le sel « disparaît » quand il se dissout : il est toujours là, la masse se conserve et l’eau a un goût salé.','Penser qu’une filtration retire le sel de l’eau salée : le sel dissous traverse le filtre.','Croire que l’air est un seul gaz, ou qu’il contient surtout du dioxygène : c’est surtout du diazote.'],
  ['Mélange homogène : une seule phase visible ; hétérogène : plusieurs constituants visibles.','Décantation, filtration, évaporation et tamisage séparent les constituants d’un mélange.','Masse de la solution = masse du solvant + masse du soluté dissous ; une solution peut être saturée.']),
 g:mix([sort({'tamisage':['séparer le sable fin des cailloux','retirer les grumeaux de la farine'],'décantation':['laisser reposer l’eau boueuse pour que la terre tombe au fond','séparer l’huile et l’eau avec une ampoule à décanter'],'filtration':['retenir le marc de café dans un filtre','obtenir une eau limpide à partir d’eau boueuse avec un papier filtre'],'évaporation':['récupérer le sel de l’eau de mer dans un marais salant','récupérer le sel d’une eau salée en la chauffant doucement']},{q:'Quelle technique utiliser pour %s ?',e:(x,c)=>`Pour ${x}, la technique adaptée est : ${c}.`}),2],
  [sort({'mélange homogène':['de l’eau salée','du sirop de grenadine dilué dans l’eau','l’air','du thé sucré','du vinaigre'],'mélange hétérogène':['de l’eau boueuse','une vinaigrette au repos','du sable mélangé à de l’eau','du jus d’orange avec pulpe','de l’eau gazeuse avec des bulles']},{q:'« %s » : c’est un…',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} : ${c}, car on distingue ${c==='mélange homogène'?'une seule phase':'au moins deux constituants'} à l’œil nu.`}),2],
  [d=>{const w=P([100,150,200,250,300,400,500]),s=d===1?R(2,20):R(5,60);
    return num(`On dissout complètement <b>${s} g</b> de sel dans <b>${w} g</b> d’eau. Quelle est la masse de l’eau salée obtenue ?`,w+s,{unit:'g',expl:`La masse se conserve lors d’une dissolution : ${w} + ${s} = <b>${w+s} g</b>.`,hint:'Rien ne disparaît.'});},2],
  [d=>{const w=P([50,100,150,200,250]),max=rd(0.36*w);let m=R(Math.round(max*.5),Math.round(max*1.6));if(Math.abs(m-max)<1)m+=2;const rest=Math.max(0,rd(m-max));
    if(d===1||Math.random()<.5)return ch(`On admet qu’à 20 °C on peut dissoudre au maximum 36 g de sel dans 100 g d’eau. On verse <b>${m} g</b> de sel dans <b>${w} g</b> d’eau et on agite longtemps. Que observe-t-on ?`.replace('Que observe','Qu’observe'),rest>0?'il reste du sel non dissous au fond : la solution est saturée':'tout le sel se dissout : la solution n’est pas saturée',[rest>0?'tout le sel se dissout : la solution n’est pas saturée':'il reste du sel non dissous au fond : la solution est saturée','le sel fond et devient liquide','le sel s’évapore'],{expl:`Dans ${w} g d’eau, on peut dissoudre au maximum 36 × ${w} ÷ 100 = ${F(max)} g. ${m} g ${rest>0?'dépasse':'ne dépasse pas'} cette limite.`,hint:'Calcule d’abord la masse maximale qu’on peut dissoudre.'});
    return num(`On admet qu’à 20 °C on peut dissoudre au maximum 36 g de sel dans 100 g d’eau. On verse <b>${m} g</b> de sel dans <b>${w} g</b> d’eau. Quelle masse de sel reste non dissoute au fond ?`,rest,{unit:'g',expl:`Maximum dissous : 36 × ${w} ÷ 100 = ${F(max)} g. Reste : ${rest>0?`${m} − ${F(max)} = <b>${F(rest)} g</b>`:'<b>0 g</b>, tout est dissous'}.`,hint:'Masse versée − masse maximale dissoute.'});},2],
  [d=>{const V=P([10,50,100,200,300,500,1000]);const g=P([['dioxygène',21],['diazote',78]]);
    return num(`On admet que l’air contient en volume ${g[1]} % de ${g[0]}. Quel volume de ${g[0]} y a-t-il dans <b>${nf(V)} L</b> d’air ?`,rd(V*g[1]/100),{unit:'L',expl:`${g[1]} % de ${nf(V)} L = ${nf(V)} × ${g[1]} ÷ 100 = <b>${F(rd(V*g[1]/100))} L</b>.`,hint:'Calcul d’un pourcentage.'});},1],
  [bank([['Dans une ampoule à décanter contenant de l’eau et de l’huile, l’huile est…','au-dessus',['au-dessous','mélangée à l’eau','au milieu de l’eau'],'Pour un même volume, l’huile a une masse plus petite que l’eau : elle forme la couche du haut.'],
   ['Dans l’eau salée, le sel est…','le soluté',['le solvant','le filtrat','le précipité'],'Le soluté est l’espèce dissoute ; le solvant (l’eau) est celle qui dissout.'],
   ['Le liquide recueilli après une filtration s’appelle…','le filtrat',['le résidu','le soluté','le décantat'],'Le filtrat est le liquide qui a traversé le filtre ; le résidu reste dans le filtre.'],
   ['Une filtration permet-elle de récupérer le sel dissous dans l’eau salée ?','non, le sel dissous traverse le filtre',['oui, le filtre retient le sel','oui, si on filtre deux fois','oui, avec un filtre à café'],'Les particules de sel dissous sont trop petites : il faut une évaporation.',2],
   ['Quel gaz est le plus abondant dans l’air ?','le diazote',['le dioxygène','le dioxyde de carbone','la vapeur d’eau'],'L’air contient environ 78 % de diazote et 21 % de dioxygène.'],
   ['Lequel de ces gaz est un gaz à effet de serre ?','le dioxyde de carbone',['le diazote','le dioxygène','l’argon'],'Dioxyde de carbone, méthane, vapeur d’eau et protoxyde d’azote contribuent à l’effet de serre.',2],
   ['Vinaigre + bicarbonate de soude : il se forme des bulles. Il s’agit…','d’une transformation chimique (un gaz est produit)',['d’une simple dissolution','d’une fusion','d’une évaporation'],'L’apparition d’une nouvelle espèce (ici un gaz, le dioxyde de carbone) signe une transformation chimique.',3],
   ['Le pictogramme représentant une flamme signale un produit…','inflammable',['corrosif','toxique','dangereux pour l’environnement'],'La flamme indique que le produit peut prendre feu facilement.',2],
   ['Le pictogramme montrant un liquide qui ronge une main et une surface signale un produit…','corrosif',['inflammable','explosif','comburant'],'Un produit corrosif attaque la peau et les matériaux (ex. : déboucheur, détartrant puissant).',2],
   ['Deux liquides qui forment deux couches distinctes sont dits…','non miscibles',['miscibles','solubles','saturés'],'Eau et huile ne se mélangent pas : elles sont non miscibles.',2]]),3])},

{id:'pc6c',name:'Masse, volume et mesures',icon:'⚖️',domain:'Mesures',
 refs:[REF6,T6('États et constitution de la matière à l’échelle macroscopique — Masse et volume')],
 tip:'Dans un tableau de conversion, chaque colonne vaut 10 fois la suivante ; et retiens les ponts : 1 L = 1 dm³ et 1 mL = 1 cm³.',
 c:C(`Une bouteille d’eau de 1,5 L, une canette de 33 cL, un paquet de 500 g de pâtes, une seringue de 5 mL : chaque objet porte une <b>masse</b> ou un <b>volume</b>. Comment les mesurer, les convertir et ne pas les confondre ?`,
  [T('Masse : combien de matière ?',`<p>La <b>masse</b> se mesure avec une <b>balance</b> ; son unité légale est le <b>kilogramme (kg)</b>. On utilise aussi la tonne (1 t = 1 000 kg), le quintal (1 q = 100 kg), le gramme (1 kg = 1 000 g) et le milligramme (1 g = 1 000 mg).</p><p>Pour peser un liquide, on pose le récipient vide et on appuie sur « tare » (la balance affiche 0), ou bien on fait la différence : m(liquide) = m(récipient plein) − m(récipient vide).</p>`),
   T('Volume : quelle place occupe-t-il ?',`<p>Le <b>volume</b> d’un liquide se mesure avec une <b>éprouvette graduée</b> : l’œil à hauteur du liquide, on lit la graduation au <b>bas du ménisque</b>. Unités : le litre (L), le décilitre (dL), le centilitre (cL), le millilitre (mL) ; et le mètre cube (m³), le décimètre cube (dm³), le centimètre cube (cm³).</p><p><b>1 L = 1 dm³ = 1 000 mL = 1 000 cm³</b> ; <b>1 mL = 1 cm³</b> ; 1 m³ = 1 000 L.</p><p>Volume d’un solide qui coule : on le plonge dans l’éprouvette ; V(solide) = V(final) − V(initial). Un gaz se mesure aussi par <b>déplacement d’eau</b> dans une éprouvette retournée.</p>`),
   T('Masse et volume sont deux grandeurs différentes',`<p>Un litre de plumes et un litre de plomb ont le même volume mais pas du tout la même masse. Pour <b>un même matériau</b> (homogène), la masse est <b>proportionnelle</b> au volume : si 10 cm³ d’aluminium ont une masse de 27 g, alors 30 cm³ ont une masse de 81 g. Deux liquides qui ne se mélangent pas se superposent : celui qui a la plus grande masse pour un même volume va dessous.</p>`)],
  [{q:'Convertir 0,75 L en mL puis en cm³.',s:['1 L = 1 000 mL : on multiplie par 1 000.','0,75 × 1 000 = 750 mL.','1 mL = 1 cm³, donc 750 mL = 750 cm³.']},
   {q:'Une éprouvette contient 50 mL d’eau. On y plonge un caillou : le niveau monte à 68 mL. Volume du caillou ?',s:['Le caillou a pris la place d’un volume d’eau égal au sien.','V = V(final) − V(initial) = 68 − 50.','Le caillou a un volume de 18 mL, soit 18 cm³.']}],
  ['J’identifie la grandeur : masse (balance, kg) ou volume (éprouvette, L ou m³).','Pour convertir, je repère si je vais vers une unité plus petite (je multiplie) ou plus grande (je divise).','J’utilise les ponts 1 L = 1 dm³ et 1 mL = 1 cm³.','Je vérifie que le résultat est vraisemblable.'],
  ['Confondre masse et volume : « 1 L de sable pèse 1 kg » est faux, ce n’est vrai que pour l’eau.','Se tromper de sens : 2,5 L = 2 500 mL (et pas 0,0025 mL).','Lire l’éprouvette en haut du ménisque ou l’œil au-dessus du liquide.'],
  ['Masse : balance, kilogramme ; 1 kg = 1 000 g ; 1 t = 1 000 kg.','Volume : éprouvette, litre ; 1 L = 1 dm³ = 1 000 mL ; 1 mL = 1 cm³.','Pour un même matériau, la masse est proportionnelle au volume.']),
 g:mix([d=>conv(VOL,d,'vol'),3],[d=>conv(MAS,d,'mas'),3],
  [d=>{const v1=R(3,7)*10,v=R(d===1?5:2,d===1?25:39)+(d===3?R(1,9)/2:0);const v2=rd(v1+v);const o=P(['un caillou','une bille de verre','une clé en acier','un écrou']);
    return num(`Une éprouvette contient <b>${v1} mL</b> d’eau. On y plonge ${o} : le niveau monte à <b>${F(v2)} mL</b>. Quel est son volume en cm³ ?`,v,{unit:'cm³',expl:`V = ${F(v2)} − ${v1} = ${F(v)} mL, et 1 mL = 1 cm³ : <b>${F(v)} cm³</b>.`,hint:'Volume final − volume initial.'});},2],
  [d=>{const e=R(80,250),l=R(50,500);const liq=P(['d’eau','d’huile','de lait','de jus de fruit']);
    return num(`Un bécher vide a une masse de <b>${e} g</b>. Rempli ${liq}, il a une masse de <b>${e+l} g</b>. Quelle est la masse ${liq} ?`,l,{unit:'g',expl:`m(liquide) = m(plein) − m(vide) = ${e+l} − ${e} = <b>${l} g</b>. On aurait aussi pu tarer la balance avec le bécher vide.`,hint:'Fais la différence des deux pesées.'});},2],
  [d=>{const [n,rho]=P([['d’aluminium',2.7],['de fer',7.87],['d’huile',0.92],['d’eau',1],['de cuivre',8.96]]);const v1=P([5,10,20,25,50]);const k=P([2,3,4,5,10]);const m1=rd(rho*v1),v2=v1*k;
    return num(`${v1} cm³ ${n} ont une masse de <b>${F(m1)} g</b>. Quelle est la masse de <b>${v2} cm³</b> ${n} ?`,rd(m1*k),{unit:'g',expl:`Pour un même matériau, la masse est proportionnelle au volume. Le volume est multiplié par ${k}, donc la masse aussi : ${F(m1)} × ${k} = <b>${F(rd(m1*k))} g</b>.`,hint:'Situation de proportionnalité.'});},2],
  [d=>{const lo=P([10,20,40,50,100]),n=P([5,10]),stp=rd(10/n*(lo>=50?1:1));const step=lo>=40?P([1,2]):P([1,2]);const k=R(1,9);const v=lo+k*step;
    return num(`Sur une éprouvette, chaque petite graduation vaut <b>${step} mL</b>. Le bas du ménisque est sur la ${k}${k===1?'re':'e'} graduation au-dessus du trait « ${lo} mL ». Quel volume lit-on ?`,v,{unit:'mL',expl:`${lo} + ${k} × ${step} = <b>${v} mL</b>. On lit toujours au bas du ménisque, l’œil à la hauteur du liquide.`,hint:'Compte les graduations à partir du trait repéré.'});},1],
  [bank([['Quel instrument mesure une masse ?','une balance',['une éprouvette graduée','un thermomètre','un chronomètre'],'La balance mesure la masse ; l’éprouvette mesure un volume.'],
   ['Où lit-on le volume dans une éprouvette ?','au bas du ménisque, l’œil à la hauteur du liquide',['en haut du ménisque','au bord du verre, l’œil au-dessus','n’importe où'],'La surface de l’eau se creuse au centre (ménisque) : on lit le bas de ce creux.'],
   ['Un litre de sable a-t-il une masse de 1 kg ?','non, seul un litre d’eau a une masse d’environ 1 kg',['oui, comme tout liquide ou solide','oui, car 1 L = 1 kg','non, il a une masse de 1 g'],'Masse et volume sont deux grandeurs différentes : 1 L de sable a une masse d’environ 1,5 kg.',2],
   ['Que fait la touche « tare » d’une balance ?','elle remet l’affichage à zéro avec le récipient posé',['elle double la masse','elle convertit en litres','elle mesure le volume'],'On tare avec le récipient vide pour lire directement la masse du contenu.'],
   ['Deux liquides non miscibles sont superposés. Lequel est en dessous ?','celui qui a la plus grande masse pour un même volume',['celui qui a le plus grand volume','celui qui a été versé en premier','celui qui est le plus coloré'],'On compare les masses d’un même volume de chaque liquide (par exemple 10 mL).',3],
   {n:'Combien de mL dans 1 dm³ ?',a:1000,u:'mL',e:'1 dm³ = 1 L = 1 000 mL.',d:2},
   {n:'Combien de kg dans 3 quintaux ?',a:300,u:'kg',e:'1 q = 100 kg, donc 3 q = 300 kg.',d:2},
   ['Comment mesurer le volume d’un gaz produit par une expérience ?','en le recueillant par déplacement d’eau dans une éprouvette retournée',['avec une balance','avec une règle graduée','avec un thermomètre'],'Le gaz chasse l’eau de l’éprouvette retournée : le volume d’eau chassée est égal au volume de gaz.',3]]),2])},

{id:'pc6d',name:'Température et transferts thermiques',icon:'🌡️',domain:'Énergie',
 refs:[REF6,T6('États et constitution de la matière à l’échelle macroscopique — Propriétés de la matière')],
 tip:'Sur une courbe de température, cherche d’abord la partie horizontale : c’est le palier du changement d’état d’un corps pur.',
 c:C(`Pourquoi une cuillère en métal plongée dans une soupe chaude devient-elle vite brûlante, alors qu’une cuillère en bois reste tiède ? Et pourquoi la température de l’eau glacée ne bouge-t-elle pas tant qu’il reste de la glace ?`,
  [T('Mesurer une température',`<p>La <b>température</b> se mesure avec un <b>thermomètre</b>, en <b>degrés Celsius (°C)</b>. On plonge le réservoir dans le milieu, sans toucher les parois, et on attend que l’affichage se stabilise. Une température peut être négative : −5 °C est plus froid que 0 °C.</p><p>Un <b>écart de température</b> se calcule par différence : de −4 °C à 12 °C, la température augmente de 16 °C.</p>`),
   T('Les paliers de changement d’état',`<p>On chauffe de la glace pilée en relevant sa température chaque minute. La température monte jusqu’à 0 °C, puis <b>reste constante à 0 °C</b> tant qu’il reste de la glace : c’est le <b>palier de fusion</b>. Ensuite, quand tout est liquide, elle remonte. Au refroidissement, on observe un <b>palier de solidification</b> à la même température.</p><p>Un <b>corps pur</b> change d’état à température constante ; un <b>mélange</b> (eau salée) ne présente pas de vrai palier.</p>`),
   T('Conducteurs et isolants thermiques',`<p>L’énergie thermique passe toujours spontanément du corps <b>le plus chaud</b> vers le corps <b>le plus froid</b>, jusqu’à ce que leurs températures soient égales. Les <b>métaux</b> (fer, cuivre, aluminium) sont de bons <b>conducteurs thermiques</b>. Le bois, le plastique, la laine, le polystyrène et l’<b>air immobile</b> sont des <b>isolants thermiques</b> : ils ralentissent ce transfert. Un pull ne « produit » pas de chaleur : il ralentit la perte d’énergie de ton corps.</p>`)],
  [{q:'On chauffe de la glace : 0 min : −6 °C ; 1 min : −3 °C ; 2 min : 0 °C ; 3 min : 0 °C ; 4 min : 0 °C ; 5 min : 4 °C. Interprète.',s:['De 0 à 2 min, la glace se réchauffe : elle est solide.','De 2 à 4 min, la température reste à 0 °C : c’est le palier de fusion, glace et eau liquide coexistent.','Après 4 min, toute la glace a fondu : l’eau liquide se réchauffe.']}],
  ['Je lis les axes : le temps en abscisse (min), la température en ordonnée (°C).','Je repère les parties qui montent, qui descendent et les paliers horizontaux.','Pour un palier, je relève sa température et sa durée (instant de fin − instant de début).','J’en déduis l’état du corps dans chaque partie.'],
  ['Croire qu’un pull ou une couverture « chauffe » : ils isolent, ils ne produisent pas d’énergie.','Penser que le froid « entre » dans une boisson : c’est l’énergie thermique qui sort de la boisson vers l’extérieur plus froid.','Croire que la température continue de monter pendant que la glace fond.'],
  ['La température se mesure au thermomètre, en °C.','Un corps pur change d’état à température constante : palier.','Les métaux conduisent bien l’énergie thermique ; bois, plastique, laine et air immobile sont isolants.']),
 g:mix([d=>curveQ(d,6),4],
  [d=>{const a=R(-20,25),b=R(-20,40);if(a===b)return num('De 12 °C à 30 °C, de combien de degrés la température a-t-elle augmenté ?',18,{unit:'°C',expl:'30 − 12 = <b>18 °C</b>.'});const up=b>a;
    return num(`La température passe de <b>${nf(a)} °C</b> à <b>${nf(b)} °C</b>. De combien de degrés a-t-elle ${up?'augmenté':'diminué'} ?`,Math.abs(b-a),{unit:'°C',expl:`Écart = ${up?`${nf(b)} − (${nf(a)})`:`${nf(a)} − (${nf(b)})`} = <b>${Math.abs(b-a)} °C</b>. On peut compter sur une droite graduée en passant par 0 °C.`,hint:'Utilise une droite graduée.'});},2],
  [sort({'bon conducteur thermique':['une casserole en cuivre','une cuillère en acier','une feuille d’aluminium','un radiateur en fonte (fer)'],'isolant thermique':['une manique en tissu épais','une cuillère en bois','une boîte en polystyrène','la laine d’un pull','le double vitrage (couche d’air immobile)','une poignée en plastique']},{q:'« %s » : c’est plutôt…',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} : ${c}. Les métaux conduisent bien l’énergie thermique, les matériaux contenant de l’air immobile isolent.`}),2],
  [bank([['Une canette froide est posée dans une pièce à 22 °C. Que se passe-t-il ?','elle reçoit de l’énergie thermique de l’air et se réchauffe',['elle cède du froid à l’air','rien, elle reste froide','elle se refroidit encore'],'L’énergie thermique va du plus chaud (l’air) vers le plus froid (la canette).',2],
   ['Pourquoi les poignées de casserole sont-elles en bois ou en plastique ?','ce sont des isolants thermiques',['ce sont des conducteurs thermiques','elles sont plus lourdes','elles fondent moins'],'Un isolant ralentit le passage de l’énergie thermique : on ne se brûle pas.'],
   ['Un pull en laine…','ralentit la perte d’énergie thermique du corps',['produit de la chaleur','empêche le froid d’entrer','fait monter la température du corps'],'La laine emprisonne de l’air immobile, très isolant.',2],
   ['Pendant la fusion de la glace pure, la température…','reste constante à 0 °C',['monte régulièrement','baisse','dépend de la quantité de glace'],'C’est le palier de fusion : l’énergie reçue sert à faire fondre la glace.'],
   ['Avec quoi mesure-t-on une température ?','un thermomètre',['un baromètre','une balance','un ampèremètre'],'Le thermomètre indique la température en degrés Celsius.'],
   ['La courbe de refroidissement d’un liquide ne présente pas de palier. On en déduit que…','c’est un mélange',['c’est un corps pur','c’est de l’eau pure','il ne se solidifie jamais'],'Un corps pur se solidifie à température constante (palier) ; un mélange non.',3],
   ['Deux verres d’eau, l’un à 60 °C, l’autre à 20 °C, sont mis en contact longtemps. À la fin…','ils ont la même température',['le plus chaud est encore plus chaud','le plus froid est devenu le plus chaud','rien ne change'],'Le transfert thermique s’arrête quand les températures sont égales.',2],
   ['Dans quelle unité usuelle exprime-t-on une température en France ?','le degré Celsius (°C)',['le joule (J)','le watt (W)','le kilogramme (kg)'],'Le degré Celsius est l’unité usuelle de température.']]),2])},

{id:'pc6e',name:'Décrire un mouvement',icon:'🚲',domain:'Mouvement',
 refs:[REF6,T6('Différents types de mouvement')],
 tip:'Avant de dire « il bouge » ou « il est immobile », précise toujours « par rapport à quoi ».',
 c:C(`Assis dans un train qui roule, tu lis tranquillement : es-tu immobile ou en mouvement ? Les deux ! Tout dépend de l’objet par rapport auquel on décrit le mouvement. Décrire un mouvement, c’est préciser un <b>point de vue</b>, une <b>trajectoire</b> et l’évolution de la <b>vitesse</b>.`,
  [T('Toujours « par rapport à »',`<p>Un mouvement se décrit <b>par rapport à</b> un objet de référence (l’observateur). Le passager est <b>immobile par rapport au train</b> mais <b>en mouvement par rapport au quai</b>. Du point de vue de la cour de récréation, le Soleil décrit une courbe dans le ciel ; du point de vue du Soleil (héliocentrique), c’est la Terre qui tourne autour de lui.</p><p>La Terre tourne sur elle-même autour de l’axe des pôles en <b>24 heures</b> (un jour) et autour du Soleil en <b>environ 365,25 jours</b> (une année).</p>`),
   T('Trajectoire et évolution de la vitesse',`<p>La <b>trajectoire</b> est l’ensemble des positions successives d’un point de l’objet. Elle est <b>rectiligne</b> (droite : un train sur une voie droite), <b>circulaire</b> (cercle : la valve d’une roue par rapport à l’axe, un point d’une toupie) ou <b>curviligne</b> (courbe quelconque : un ballon lancé).</p><p>Sur une <b>chronophotographie</b> (positions prises à intervalles de temps égaux) : des écarts égaux → mouvement <b>uniforme</b> (vitesse constante) ; des écarts qui augmentent → mouvement <b>accéléré</b> ; des écarts qui diminuent → mouvement <b>ralenti</b>.</p>`),
   T('Distances et durées',`<p>Une <b>durée</b> est l’intervalle entre deux instants. Conversions utiles : 1 km = 1 000 m ; 1 m = 100 cm ; 1 h = 60 min = 3 600 s ; 1 jour = 24 h. La distance Terre-Soleil vaut environ 150 millions de kilomètres.</p>`)],
  [{q:'Positions d’une bille photographiée toutes les 0,1 s : 0 cm ; 2 cm ; 5 cm ; 9 cm ; 14 cm. Décris son mouvement.',s:['Je calcule les écarts : 2 cm, 3 cm, 4 cm, 5 cm.','Les écarts augmentent pour des durées égales : la bille parcourt de plus en plus de distance.','Le mouvement est accéléré ; si les points sont alignés, il est rectiligne accéléré.']}],
  ['Je choisis et je nomme l’objet de référence (« par rapport à… »).','Je décris la forme de la trajectoire : rectiligne, circulaire ou curviligne.','Je compare les écarts entre positions successives pour savoir si la vitesse est constante, augmente ou diminue.','Je convertis distances et durées si nécessaire.'],
  ['Dire qu’un objet est immobile sans préciser par rapport à quoi.','Croire que le Soleil tourne autour de la Terre parce qu’on le voit se déplacer dans le ciel : c’est la rotation de la Terre sur elle-même.','Confondre durée (combien de temps) et instant (à quelle heure).'],
  ['Un mouvement se décrit toujours par rapport à un objet de référence.','Trajectoire rectiligne, circulaire ou curviligne ; mouvement uniforme, accéléré ou ralenti.','La Terre tourne sur elle-même en 24 h et autour du Soleil en environ 365 jours.']),
 g:mix([d=>{const S=[['un passager assis dans un bus qui roule','au bus','à la route'],['un enfant assis sur un manège qui tourne','au siège du manège','au sol'],['une valise posée dans le coffre d’une voiture qui roule','à la voiture','à un arbre au bord de la route'],['un astronaute assis dans la Station spatiale internationale','à la Station spatiale','à la Terre'],['un voyageur debout immobile sur un escalator qui monte','à la marche de l’escalator','au sol du magasin'],['un pilote assis dans un avion en vol','à son siège','à la piste de l’aéroport']];
    const [o,a,b]=P(S);const im=Math.random()<.5;return ch(`Par rapport <b>${im?a:b}</b>, ${o} est…`,im?'immobile':'en mouvement',[im?'en mouvement':'immobile','immobile et en mouvement à la fois','on ne peut pas savoir'],{expl:`Par rapport ${a}, sa position ne change pas : immobile. Par rapport ${b}, sa position change : en mouvement. Ici, on raisonne par rapport ${im?a:b}.`,hint:'Sa distance à l’objet de référence change-t-elle ?'});},3],
  [d=>{const kind=P(['uniforme','accéléré','ralenti']);const s=R(2,6),k=R(1,3),n=d===1?4:5;let gaps=[];for(let i=0;i<n;i++)gaps.push(kind==='uniforme'?s:kind==='accéléré'?s+i*k:s+(n-1-i)*k);
    const pos=[0];gaps.forEach(g=>pos.push(pos[pos.length-1]+g));const L={uniforme:'uniforme (vitesse constante)',accéléré:'accéléré (la vitesse augmente)',ralenti:'ralenti (la vitesse diminue)'};
    return ch(`Un chariot se déplace en ligne droite. On repère sa position toutes les 0,5 s : ${pos.map(x=>x+' cm').join(' ; ')}. Son mouvement est…`,L[kind],Object.values(L).filter(x=>x!==L[kind]).concat(['circulaire']),{expl:`Écarts successifs : ${gaps.join(' cm, ')} cm. ${kind==='uniforme'?'Ils sont égaux':kind==='accéléré'?'Ils augmentent':'Ils diminuent'} pour des durées égales : mouvement <b>${L[kind]}</b>.`,hint:'Calcule la distance parcourue pendant chaque intervalle.'});},3],
  [sort({'rectiligne':['un train sur une voie droite, par rapport aux rails','une bille qui tombe verticalement, par rapport au sol','un ascenseur, par rapport à l’immeuble'],'circulaire':['la valve d’une roue de vélo, par rapport à l’axe de la roue','un point d’une toupie, par rapport à son axe','l’extrémité d’une aiguille de montre, par rapport au cadran','une nacelle de grande roue, par rapport à l’axe de la roue'],'curviligne (courbe quelconque)':['un ballon de basket lancé vers le panier, par rapport au sol','une feuille morte qui tombe en tourbillonnant, par rapport au sol']},{q:'Quelle est la trajectoire : %s ?',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} : trajectoire ${c}.`}),2],
  [d=>{const C2=[['km','m',1000],['m','cm',100],['h','min',60],['min','s',60],['h','s',3600],['jour','h',24]];const [a,b,f]=P(d===1?C2.slice(0,4):C2);const v=d===3?P([R(2,9)+.5,R(2,30)]):R(2,12);const res=rd(v*f);
    const pl=(u,x)=>u==='jour'&&x>=2?'jours':u;
    return num(`Convertis <b>${F(v)} ${pl(a,v)}</b> en ${b==='h'?'heures':b}.`,res,{unit:b,expl:`1 ${a} = ${f} ${b}, donc ${F(v)} × ${f} = <b>${F(res)} ${b}</b>.`,hint:`1 ${a} = ${f} ${b}.`});},2],
  [bank([['La durée d’un jour correspond…','à la rotation de la Terre sur elle-même',['à la révolution de la Terre autour du Soleil','au tour de la Lune autour de la Terre','à la rotation du Soleil autour de la Terre'],'La Terre fait un tour sur elle-même autour de l’axe des pôles en 24 h.'],
   ['La durée d’une année correspond…','à la révolution de la Terre autour du Soleil',['à la rotation de la Terre sur elle-même','au tour de la Lune autour de la Terre','à un tour du Soleil autour de la Terre'],'La Terre fait le tour du Soleil en environ 365,25 jours.'],
   ['Du point de vue de la cour de récréation, le Soleil…','décrit une courbe dans le ciel',['est immobile','tourne autour de l’école en 1 an','reste au zénith toute la journée'],'Par rapport au sol, le Soleil semble se lever à l’est et se coucher à l’ouest, à cause de la rotation de la Terre.',2],
   ['Du point de vue héliocentrique (par rapport au Soleil), la Terre…','tourne autour du Soleil',['est immobile','est au centre du système solaire','tourne autour de la Lune'],'Héliocentrique signifie « Soleil au centre ».',2],
   {n:'Combien d’heures la Terre met-elle pour faire un tour sur elle-même ?',a:24,u:'h',e:'Une rotation complète dure environ 24 h : c’est la durée d’un jour.'},
   ['Une trajectoire est…','l’ensemble des positions successives occupées par un point de l’objet',['la vitesse de l’objet','la distance totale parcourue','la durée du trajet'],'La trajectoire est la « trace » laissée par le point en mouvement.'],
   ['La distance moyenne entre la Terre et le Soleil est d’environ…','150 millions de km',['150 000 km','15 000 km','150 milliards de km'],'Environ 150 millions de kilomètres, soit 1,5 × 10<sup>8</sup> km.',3]]),2])},

{id:'pc6f',name:'Vitesse : comparer et calculer',icon:'⏱️',domain:'Mouvement',
 refs:[REF6,T6('Différents types de mouvement — Mouvements'),'Programme 2023 : « En classe de sixième, seul le calcul de la valeur de la vitesse à partir de la distance parcourue et de la durée de déplacement dans le cas d’un mouvement uniforme est exigible » (BO n°25 du 22 juin 2023)'],
 tip:'Vitesse = distance ÷ durée : divise toujours la distance par la durée, et construis l’unité avec les unités utilisées (km et h → km/h).',
 c:C(`Léa court 100 m en 20 s, Tom court 60 m en 10 s. Qui est le plus rapide ? Celui qui a couru la plus grande distance ? Non : il faut comparer les distances parcourues <b>pendant une même durée</b>. C’est ce que mesure la <b>vitesse</b>.`,
  [T('Calculer une vitesse',`<p>Pour un mouvement <b>uniforme</b>, la valeur de la vitesse est la distance parcourue divisée par la durée du parcours : <b>v = d ÷ t</b>.</p><p>Si d est en mètres et t en secondes, v est en <b>mètres par seconde (m/s)</b> ; si d est en kilomètres et t en heures, v est en <b>kilomètres par heure (km/h)</b>. Exemple : 100 m en 20 s → v = 100 ÷ 20 = 5 m/s : chaque seconde, Léa parcourt 5 m.</p>`),
   T('Comparer des vitesses',`<p>Pour comparer deux vitesses, elles doivent être exprimées <b>dans la même unité</b>. Léa : 5 m/s ; Tom : 60 ÷ 10 = 6 m/s : Tom est plus rapide, même s’il a couru moins loin.</p><p>Si la durée est donnée en minutes, on peut chercher la distance parcourue en 1 heure : 15 km en 30 min, c’est 30 km en 60 min, donc 30 km/h. Quelques ordres de grandeur : marcheur ≈ 5 km/h, cycliste ≈ 20 km/h, voiture sur autoroute ≤ 130 km/h.</p>`)],
  [{q:'Un cycliste parcourt 24 km en 2 h à vitesse constante. Quelle est sa vitesse ?',s:['Données : d = 24 km et t = 2 h.','v = d ÷ t = 24 ÷ 2 = 12.','Unités : km et h, donc v = 12 km/h.']},
   {q:'Un robot parcourt 90 cm en 6 s. Quelle est sa vitesse ?',s:['d = 90 cm et t = 6 s.','v = 90 ÷ 6 = 15.','v = 15 cm/s.']}],
  ['Je relève la distance d et la durée t, avec leurs unités.','Je calcule v = d ÷ t (distance divisée par durée).','J’écris l’unité : unité de distance / unité de durée.','Pour comparer, j’exprime toutes les vitesses dans la même unité.'],
  ['Diviser la durée par la distance (t ÷ d) au lieu de d ÷ t.','Oublier l’unité ou écrire « km/h » alors que les données sont en mètres et secondes.','Comparer des vitesses exprimées dans des unités différentes.'],
  ['v = d ÷ t pour un mouvement uniforme.','m et s → m/s ; km et h → km/h.','On compare des vitesses dans la même unité.']),
 g:mix([vit6,6],
  [d=>{const a=[R(40,200),R(8,40)],b=[R(40,200),R(8,40)];const va=rd(a[0]/a[1],2),vb=rd(b[0]/b[1],2);if(Math.abs(va-vb)<0.2)return vit6(d);
    const g=va>vb?'Ali':'Inès';return ch(`Ali parcourt ${a[0]} m en ${a[1]} s ; Inès parcourt ${b[0]} m en ${b[1]} s. Qui est le plus rapide ?`,g,[g==='Ali'?'Inès':'Ali','ils ont la même vitesse','celui qui a parcouru la plus grande distance'],{expl:`Ali : ${a[0]} ÷ ${a[1]} ≈ ${F(va)} m/s ; Inès : ${b[0]} ÷ ${b[1]} ≈ ${F(vb)} m/s. Le plus rapide est <b>${g}</b>.`,hint:'Calcule les deux vitesses.'});},2],
  [bank([['Quelle formule donne la vitesse ?','v = d ÷ t',['v = t ÷ d','v = d × t','v = d + t'],'La vitesse est la distance parcourue par unité de durée.'],
   ['Une vitesse en m/s indique…','le nombre de mètres parcourus en une seconde',['le nombre de secondes pour un mètre','la distance totale','la durée totale'],'5 m/s : 5 mètres parcourus chaque seconde.'],
   ['Lequel va le plus vite ?','une voiture à 90 km/h',['un cycliste à 20 km/h','un marcheur à 5 km/h','un coureur à 15 km/h'],'Les vitesses sont dans la même unité : on compare directement.'],
   ['Un mouvement uniforme est un mouvement…','dont la vitesse reste constante',['qui est toujours rectiligne','qui s’arrête','dont la vitesse augmente'],'« Uniforme » concerne la valeur de la vitesse, pas la forme de la trajectoire.',2],
   ['Un marcheur avance à une vitesse d’environ…','5 km/h',['50 km/h','0,5 km/h','500 km/h'],'Ordre de grandeur : 4 à 6 km/h pour la marche.',2],
   ['Un TGV en ligne droite à 300 km/h, puis à 300 km/h dans un long virage. Sa vitesse change-t-elle de valeur ?','non, la valeur reste 300 km/h',['oui, elle diminue dans le virage','oui, elle augmente','on ne peut pas savoir'],'La valeur de la vitesse est la même ; seule la direction du mouvement change.',3]]),2])},

{id:'pc6g',name:'Actions et interactions : aimants, contact, distance',icon:'🧲',domain:'Interactions',
 refs:[REF6,T6('États et constitution de la matière — Propriétés de la matière (capacité à interagir avec un aimant)'),T5('thème « Mouvement et interactions » (prolongement au cycle 4 : actions de contact et à distance)')],
 tip:'Pour chaque action, nomme l’acteur (qui agit) et le receveur (qui subit), puis demande-toi s’ils se touchent : contact ou à distance.',
 c:C(`Un aimant attire un trombone sans le toucher, la Terre fait tomber une pomme, ton pied lance un ballon. Dans chaque cas, un objet <b>agit</b> sur un autre. Comment décrire ces actions et prévoir leurs effets ?`,
  [T('Actions de contact et actions à distance',`<p>Une <b>action mécanique</b> est exercée par un <b>acteur</b> sur un <b>receveur</b>. Elle est <b>de contact</b> si les deux objets se touchent (la main qui pousse un chariot, la table qui soutient un livre, la corde qui tire une luge). Elle est <b>à distance</b> s’ils ne se touchent pas : l’attraction de la <b>Terre</b> sur tous les objets (pesanteur), l’action d’un <b>aimant</b> sur un objet en fer.</p><p>Une action peut <b>mettre en mouvement</b> un objet, <b>modifier sa vitesse</b> ou <b>sa trajectoire</b>, ou le <b>déformer</b>.</p>`),
   T('Les aimants',`<p>Un aimant attire le <b>fer</b>, l’acier (qui contient du fer), le <b>nickel</b> et le <b>cobalt</b>. Il n’attire ni l’aluminium, ni le cuivre, ni l’or, ni le bois, ni le plastique, ni le verre : tous les métaux ne sont pas attirés ! Cette propriété permet de <b>trier</b> les déchets (séparer les boîtes en acier des canettes en aluminium).</p><p>Un aimant possède deux <b>pôles</b>, nord et sud. Deux pôles de même nom se <b>repoussent</b> ; deux pôles de noms différents s’<b>attirent</b>. L’action d’un aimant traverse le papier, le carton ou le bois.</p>`),
   T('Une interaction est réciproque',`<p>Si A agit sur B, alors B agit aussi sur A : on parle d’<b>interaction</b>. Le trombone attire aussi l’aimant ; la pomme attire aussi la Terre (mais l’effet sur la Terre est imperceptible). Au cycle 4, ces actions seront modélisées par des <b>forces</b>.</p>`)],
  [{q:'Un livre est posé sur une table. Quelles actions s’exercent sur le livre ?',s:['Acteurs qui touchent le livre : la table (action de contact, elle le soutient).','Acteur qui ne le touche pas : la Terre (action à distance, elle l’attire vers le bas).','Le livre reste immobile : les deux actions se compensent.']}],
  ['Je repère le receveur (l’objet étudié).','Je liste tous les acteurs qui le touchent : actions de contact.','J’ajoute les actions à distance : la Terre (toujours), un aimant éventuel.','Je décris l’effet de chaque action : mise en mouvement, changement de vitesse ou de trajectoire, déformation.'],
  ['Croire que tous les métaux sont attirés par un aimant : l’aluminium et le cuivre ne le sont pas.','Oublier l’action de la Terre, qui agit à distance sur tous les objets.','Penser qu’un objet immobile ne subit aucune action : le livre est soutenu par la table et attiré par la Terre.'],
  ['Action de contact : acteur et receveur se touchent ; action à distance : ils ne se touchent pas.','Un aimant attire le fer, le nickel et le cobalt ; deux pôles de même nom se repoussent.','Une action peut mettre en mouvement, modifier une vitesse ou une trajectoire, déformer.']),
 g:mix([sort({'action de contact':['la main qui pousse un chariot','le pied qui frappe un ballon','la corde qui tire une luge','la table qui soutient un vase','le vent qui gonfle une voile','la raquette qui frappe une balle','l’eau qui fait flotter un bateau'],'action à distance':['la Terre qui attire une pomme qui tombe','un aimant qui attire un trombone sans le toucher','deux aimants qui se repoussent sans se toucher','la Terre qui attire la Lune','le Soleil qui attire la Terre']},{q:'« %s » : de quel type d’action s’agit-il ?',e:(x,c)=>`« ${x} » : ${c}, car l’acteur et le receveur ${c==='action de contact'?'se touchent':'ne se touchent pas'}.`}),4],
  [sort({'l’aimant l’attire':['un clou en fer','un trombone en acier','une pièce en nickel','une vis en acier','une boîte de conserve en acier'],'l’aimant ne l’attire pas':['une canette en aluminium','un fil de cuivre','une bague en or','une règle en plastique','un crayon en bois','une bille de verre','une feuille de papier aluminium']},{q:'On approche un aimant : « %s ». Que se passe-t-il ?',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} : ${c}. Seuls le fer (et l’acier), le nickel et le cobalt sont attirés par un aimant.`}),3],
  [sort({'mettre en mouvement':['le pied qui frappe un ballon immobile','la main qui pousse un chariot à l’arrêt'],'modifier la vitesse ou la trajectoire':['le gardien qui dévie un tir','les freins qui ralentissent un vélo','un aimant qui dévie une bille d’acier qui roule'],'déformer':['les doigts qui écrasent de la pâte à modeler','la main qui étire un ressort','le pied qui écrase une canette vide']},{q:'Quel est l’effet principal de l’action : %s ?',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} : l’action a pour effet de ${c}.`}),2],
  [d=>{const p=[['nord','nord'],['sud','sud'],['nord','sud'],['sud','nord']];const [a,b]=P(p);const rep=a===b;
    return ch(`On approche le pôle <b>${a}</b> d’un aimant du pôle <b>${b}</b> d’un autre aimant. Que se passe-t-il ?`,rep?'ils se repoussent':'ils s’attirent',[rep?'ils s’attirent':'ils se repoussent','rien du tout','ils s’annulent et ne sont plus des aimants'],{expl:`Deux pôles de même nom se repoussent, deux pôles de noms différents s’attirent : ${a}/${b} → <b>${rep?'répulsion':'attraction'}</b>.`,hint:'Même nom : répulsion.'});},2],
  [bank([['Pour séparer des canettes en aluminium de boîtes en acier, on peut utiliser…','un aimant',['un tamis','un filtre','une loupe'],'L’acier est attiré par l’aimant, l’aluminium ne l’est pas.'],
   ['L’action de la Terre sur une pomme qui tombe est…','une action à distance',['une action de contact','une action de l’air','aucune action'],'La Terre attire la pomme sans la toucher : c’est la pesanteur.'],
   ['Un aimant attire un trombone. Le trombone agit-il sur l’aimant ?','oui, il attire aussi l’aimant',['non, seul l’aimant agit','non, le trombone n’est pas aimanté','seulement s’ils se touchent'],'Une interaction est réciproque : si A agit sur B, B agit sur A.',3],
   ['L’action d’un aimant peut-elle traverser une feuille de carton ?','oui',['non','seulement si le carton est mouillé','seulement le pôle nord'],'On peut déplacer un trombone posé sur un carton avec un aimant placé dessous.',2],
   ['Sur un livre posé immobile sur une table s’exercent…','l’action de la table et celle de la Terre',['aucune action','seulement l’action de la Terre','seulement l’action de la table'],'Contact (table) et à distance (Terre) : elles se compensent, le livre reste immobile.',3]]),2])},

{id:'pc6h',name:'Circuit électrique simple',icon:'💡',domain:'Électricité',
 refs:[REF6,T6('Signal et information — Électricité')],
 tip:'Suis la boucle avec ton doigt depuis une borne de la pile : si tu reviens à l’autre borne sans rencontrer d’ouverture ni d’isolant, le courant circule.',
 c:C(`Une lampe de poche ne s’allume plus : pile usée, lampe grillée, interrupteur cassé ou fil coupé ? Pour le savoir, il faut comprendre comment fonctionne un <b>circuit électrique</b> et savoir le schématiser.`,
  [T('Une boucle fermée',`<p>Un circuit simple comporte un <b>générateur</b> (pile), des <b>récepteurs</b> (lampe, moteur, DEL) et des <b>fils de connexion</b>, et souvent un <b>interrupteur</b>. Le courant ne circule que si la boucle est <b>fermée</b> : interrupteur fermé, aucun fil débranché, aucun élément <b>isolant</b> dans la boucle. Dans un circuit à une seule boucle, on peut <b>intervertir</b> les positions des composants sans changer le fonctionnement.</p><p>Le courant n’est pas « consommé » par la lampe : il circule tout le long de la boucle.</p>`),
   T('Conducteurs, isolants, composants',`<p>Les <b>métaux</b> (cuivre, fer, aluminium…) et le <b>graphite</b> (mine de crayon) sont des <b>conducteurs</b> électriques. Le plastique, le verre, le bois sec, le caoutchouc, le papier sont des <b>isolants</b>. Une <b>DEL</b> (diode électroluminescente) ne laisse passer le courant que dans un sens (sens passant). Un <b>moteur</b> transforme l’énergie électrique en mouvement ; une cellule <b>photovoltaïque</b> peut remplacer la pile au soleil.</p><p>Le <b>schéma normalisé</b> utilise des symboles : pile (deux traits parallèles de longueurs différentes), lampe (cercle avec une croix), interrupteur ouvert (trait levé), moteur (cercle avec un M).</p>`),
   T('Sécurité électrique',`<p>Relier directement les bornes d’une pile par un fil crée un <b>court-circuit</b> : la pile chauffe et s’use très vite. Le courant du <b>secteur (230 V)</b> est <b>dangereux</b>, voire mortel : on ne touche jamais une prise ou un fil dénudé, on n’utilise pas d’appareil électrique les mains mouillées. Les expériences se font uniquement avec des piles.</p>`)],
  [{q:'Circuit : pile, interrupteur fermé, lampe et une gomme reliée par des pinces crocodiles. La lampe ne brille pas. Pourquoi ?',s:['Je suis la boucle : pile → interrupteur fermé → lampe → gomme → pile.','La gomme est en caoutchouc ou en plastique : c’est un isolant.','La boucle est interrompue : le courant ne circule pas. Avec une clé en fer à la place, la lampe brillerait.']}],
  ['Je repère le générateur, les récepteurs et l’interrupteur.','Je suis la boucle d’une borne de la pile à l’autre.','Je vérifie : interrupteur fermé ? fils bien branchés ? aucun isolant ? DEL dans le sens passant ?','Je conclus : le courant circule ou non.'],
  ['Croire que le courant « s’use » dans la lampe et qu’il en reste moins après.','Penser qu’il suffit d’un seul fil entre la pile et la lampe : il faut une boucle fermée.','Croire que tous les matériaux brillants ou durs sont conducteurs : le verre et le plastique sont isolants.'],
  ['Le courant circule seulement dans une boucle fermée.','Métaux et graphite sont conducteurs ; plastique, verre, bois sec, caoutchouc sont isolants.','Court-circuit et secteur (230 V) sont dangereux.']),
 g:mix([d=>{const COND=[['une clé en fer',1],['une pièce de monnaie',1],['une feuille de papier aluminium',1],['la mine d’un crayon (graphite)',1],['un fil de cuivre',1],['une cuillère en acier',1],['une gomme',0],['une règle en plastique',0],['un bouchon de liège',0],['une baguette de verre',0],['un crayon en bois (côté bois)',0],['un élastique en caoutchouc',0]];
    const rec=P(['une lampe','un moteur','une DEL']);const pb=P(d===1?['aucun','inter','iso']:['aucun','inter','iso','del','aucun']);
    const obj=pb==='iso'?P(COND.filter(x=>!x[1])):P(COND.filter(x=>x[1]));const isDel=rec==='une DEL'||pb==='del';const recv=pb==='del'?'une DEL':rec;
    const inter=pb==='inter'?'ouvert':'fermé';const sens=isDel?(pb==='del'?', branchée dans le sens bloquant':', branchée dans le sens passant'):'';
    const eff={'une lampe':'la lampe brille','un moteur':'le moteur tourne','une DEL':'la DEL brille'}[recv];
    const R0={aucun:`${eff}`,inter:`rien ne fonctionne : l’interrupteur est ouvert`,iso:`rien ne fonctionne : le matériau inséré (${obj[0].replace(/^(une?|la|le) /,'')}) est isolant`,del:`rien ne fonctionne : la DEL est dans le sens bloquant`};if(!isDel)R0.del='rien ne fonctionne : le courant est entièrement consommé avant de revenir à la pile';
    const bad=Object.entries(R0).filter(([k])=>k!==pb).map(([k,v])=>v);
    return ch(`Circuit en une boucle : une pile, un interrupteur <b>${inter}</b>, ${recv}${sens} et, entre deux pinces crocodiles, ${obj[0]}. Que se passe-t-il ?`,R0[pb],bad,{expl:pb==='aucun'?`La boucle est fermée et le matériau inséré (${obj[0]}) est conducteur : le courant circule, ${eff}.`:pb==='inter'?'Un interrupteur ouvert coupe la boucle : le courant ne circule pas.':pb==='iso'?`${obj[0].charAt(0).toUpperCase()+obj[0].slice(1)} est un isolant : la boucle est interrompue.`:'Une DEL ne laisse passer le courant que dans un sens : dans le sens bloquant, le courant ne circule pas.',hint:'Suis la boucle et cherche ce qui pourrait l’interrompre.'});},4],
  [sort({'conducteur électrique':['le cuivre','le fer','l’aluminium','le graphite d’une mine de crayon','l’or','l’acier'],'isolant électrique':['le plastique','le verre','le bois sec','le caoutchouc','le papier','l’air sec','la porcelaine']},{q:'« %s » : conducteur ou isolant électrique ?',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} est un ${c}. Les métaux et le graphite conduisent le courant.`}),2],
  [bank([['Que se passe-t-il si on relie directement les deux bornes d’une pile par un fil ?','un court-circuit : la pile chauffe et s’use très vite',['la pile se recharge','rien','la pile produit plus de lumière'],'Le fil sans récepteur laisse passer un courant très intense : c’est dangereux.',2],
   ['Dans un circuit à une boucle, on échange la place de la lampe et de l’interrupteur. La lampe…','fonctionne exactement de la même façon',['ne s’allume plus','brille plus fort','brille moins'],'Dans une boucle unique, l’ordre des composants ne change rien.',2],
   ['Pourquoi ne faut-il jamais faire d’expérience avec une prise de courant ?','le secteur (230 V) peut provoquer une électrocution',['la prise est trop petite','le courant du secteur est trop faible','les prises sont isolantes'],'Le secteur est dangereux, voire mortel ; on expérimente uniquement avec des piles.'],
   ['Le symbole normalisé d’une lampe est…','un cercle avec une croix',['un cercle avec un M','deux traits parallèles','un rectangle'],'Le cercle avec un M représente un moteur ; les deux traits, une pile.',2],
   ['Le symbole formé de deux traits parallèles de longueurs différentes représente…','une pile',['une lampe','un moteur','un interrupteur fermé'],'Le grand trait est la borne +, le petit trait la borne −.',2],
   ['Le courant est-il moins intense après la lampe qu’avant ?','non, il circule dans toute la boucle',['oui, la lampe en consomme une partie','oui, il s’épuise le long des fils','il n’y a pas de courant après la lampe'],'Le courant ne s’use pas : c’est l’énergie qui est transférée à la lampe.',3],
   ['Quel composant peut remplacer la pile pour faire tourner un petit moteur au soleil ?','une cellule photovoltaïque',['une DEL','un interrupteur','une résistance'],'La cellule photovoltaïque convertit l’énergie lumineuse en énergie électrique.',3],
   ['Une DEL ne s’allume pas alors que tout est bien branché et l’interrupteur fermé. On peut…','la retourner : elle est peut-être dans le sens bloquant',['ajouter un isolant','ouvrir l’interrupteur','enlever la pile'],'La DEL ne laisse passer le courant que dans un sens.',2]]),3])},

{id:'pc6i',name:'Énergie : sources, formes et conversions',icon:'🔋',domain:'Énergie',
 refs:[REF6,T6('Ressources en énergie et conversions d’énergie')],
 tip:'Pour un convertisseur, pose-toi deux questions : quelle énergie entre ? quelle énergie sort ? Il y a presque toujours aussi de l’énergie thermique en sortie.',
 c:C(`Une éolienne tourne, ton téléphone se recharge, une voiture roule, une lampe éclaire. Partout, de l’<b>énergie</b> est utilisée, transférée et convertie. D’où vient-elle et sous quelles formes se présente-t-elle ?`,
  [T('Les formes d’énergie',`<ul class="lst"><li><b>Énergie de pesanteur</b> : liée à l’altitude (l’eau en haut d’un barrage).</li><li><b>Énergie cinétique</b> : liée au mouvement (le vent, une voiture qui roule).</li><li><b>Énergie chimique</b> : stockée dans les aliments, le bois, l’essence, une pile.</li><li><b>Énergie thermique</b> : liée à la température.</li><li><b>Énergie nucléaire</b> : stockée dans les noyaux d’uranium.</li><li><b>Énergie électrique</b> et <b>énergie lumineuse</b> : ce sont des énergies <b>transférées</b> (par le courant, par la lumière), qui ne se stockent pas telles quelles.</li></ul>`),
   T('Conversions et chaîne énergétique',`<p>Un <b>convertisseur</b> transforme une forme d’énergie en une autre. On le représente par une <b>chaîne énergétique</b> : réservoir → convertisseur → énergie utile (+ énergie thermique perdue).</p><p>Exemples : pile + moteur : énergie chimique → électrique → cinétique ; lampe : électrique → lumineuse (+ thermique) ; panneau photovoltaïque : lumineuse → électrique ; éolienne : cinétique (vent) → électrique ; « au cours de la chute d’un objet, son énergie de pesanteur est convertie en énergie cinétique ».</p>`),
   T('Ressources renouvelables ou non',`<p>Une ressource est <b>renouvelable</b> si elle se reconstitue rapidement à l’échelle d’une vie humaine : Soleil, vent, eau des rivières, bois (si on replante), géothermie. Pétrole, charbon, gaz naturel et uranium sont <b>non renouvelables</b>. Brûler des combustibles fossiles émet du <b>dioxyde de carbone</b>, gaz à effet de serre ; le nucléaire produit des déchets radioactifs. La Terre reçoit l’énergie du Soleil par la lumière qu’il émet.</p>`)],
  [{q:'Représente la chaîne énergétique d’une petite voiture électrique à piles.',s:['Réservoir : la pile, qui stocke de l’énergie chimique.','Transfert électrique vers le convertisseur : le moteur.','Le moteur fournit de l’énergie cinétique (utile) et de l’énergie thermique (perdue : il chauffe).']}],
  ['Je repère le réservoir d’énergie (forme stockée).','Je repère le convertisseur et la forme d’énergie qu’il reçoit.','Je nomme l’énergie utile en sortie et l’énergie perdue (souvent thermique).','Je classe la ressource : renouvelable ou non.'],
  ['Dire qu’une pile « produit » de l’énergie : elle convertit l’énergie chimique qu’elle stocke.','Croire que l’électricité est une source d’énergie : c’est une forme d’énergie transférée, produite à partir d’une ressource.','Classer le bois comme non renouvelable : il l’est si les forêts sont replantées.'],
  ['Formes : pesanteur, cinétique, chimique, thermique, nucléaire, électrique, lumineuse.','Un convertisseur transforme une forme d’énergie en une autre, avec souvent de l’énergie thermique perdue.','Soleil, vent, eau sont renouvelables ; pétrole, charbon, gaz, uranium ne le sont pas.']),
 g:mix([d=>{const D=[['une lampe','électrique','lumineuse (et thermique)'],['un moteur électrique','électrique','cinétique (et thermique)'],['une pile qui alimente un circuit','chimique','électrique'],['un panneau photovoltaïque','lumineuse','électrique'],['une éolienne','cinétique (le vent)','électrique'],['un radiateur électrique','électrique','thermique'],['un feu de bois','chimique','thermique et lumineuse'],['les muscles d’un cycliste','chimique (aliments)','cinétique (et thermique)'],['une turbine de barrage reliée à un alternateur','cinétique (eau en mouvement)','électrique'],['un réchaud à gaz','chimique','thermique'],['le moteur à essence d’une voiture','chimique','cinétique (et thermique)']];
    const [dev,inp,out]=P(D);const ask=Math.random()<.5;const all=D.map(x=>ask?x[1]:x[2]);
    return ch(`Quelle énergie ${ask?'<b>reçoit</b>':'<b>fournit</b> (utile)'} ${dev} ?`,ask?inp:out,shuffle(all.filter(x=>x!==(ask?inp:out))),{expl:`${dev.charAt(0).toUpperCase()+dev.slice(1)} : énergie ${inp} → énergie ${out}.`,hint:'Que reçoit-il ? Que produit-il d’utile ?'});},4],
  [sort({'renouvelable':['l’énergie solaire','l’énergie du vent','l’énergie des rivières (hydraulique)','le bois des forêts replantées','la géothermie'],'non renouvelable':['le pétrole','le charbon','le gaz naturel','l’uranium des centrales nucléaires']},{q:'Ressource : %s. Elle est…',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} : ressource ${c} à l’échelle d’une vie humaine.`}),2],
  [pairs([['énergie de pesanteur','énergie liée à l’altitude d’un objet'],['énergie cinétique','énergie liée au mouvement'],['énergie chimique','énergie stockée dans les aliments, les combustibles, les piles'],['énergie thermique','énergie liée à la température'],['énergie nucléaire','énergie stockée dans les noyaux d’uranium'],['énergie lumineuse','énergie transférée par la lumière']],{q:'Que désigne l’« %s » ?',rq:'Quel nom donne-t-on à l’%s ?'}),2],
  [bank([['Lors de la chute d’une pomme, son énergie de pesanteur est convertie en…','énergie cinétique',['énergie chimique','énergie nucléaire','énergie électrique'],'Plus la pomme descend, plus elle va vite.',2],
   ['Une lampe à incandescence chauffe beaucoup. Cette énergie thermique est…','une énergie perdue (non utile)',['l’énergie utile','une énergie stockée','de l’énergie chimique'],'L’énergie utile d’une lampe est lumineuse ; la chaleur est perdue.',2],
   ['Brûler du charbon ou du pétrole émet surtout…','du dioxyde de carbone, gaz à effet de serre',['du dioxygène','de la vapeur d’uranium','du diazote pur'],'Les combustions de combustibles fossiles rejettent du CO₂.',2],
   ['L’électricité est…','une forme d’énergie transférée par le courant',['une ressource naturelle qu’on extrait','une énergie stockée dans les fils','une source renouvelable'],'On la produit à partir d’une ressource (vent, uranium, gaz…).',3],
   ['D’où vient l’énergie que la Terre reçoit du Soleil ?','de la lumière émise par le Soleil',['de l’air chaud venu du Soleil','du vent solaire uniquement','de la Lune'],'« La Terre reçoit de l’énergie du Soleil par la lumière qu’il émet. »'],
   ['Dans un barrage, l’eau stockée en altitude possède de l’énergie…','de pesanteur',['chimique','nucléaire','lumineuse'],'L’énergie de pesanteur dépend de l’altitude.'],
   {o:['énergie chimique de la pile','énergie électrique','moteur','énergie cinétique'],q:'Remets dans l’ordre la chaîne énergétique d’un ventilateur à pile :',e:'Pile (chimique) → courant (électrique) → moteur → mouvement des pales (cinétique).',d:3}]),2])},

{id:'pc6j',name:'Lumière, ombres, jour et saisons',icon:'🔦',domain:'Signaux',
 refs:[REF6,T6('Signal et information — Lumière')],
 tip:'Dessine la source, l’objet et l’écran, puis trace des droites depuis la source qui frôlent les bords de l’objet : l’ombre est derrière l’objet.',
 c:C(`Pourquoi ton ombre est-elle très longue le soir et courte à midi ? Pourquoi fait-il nuit en France quand il fait jour en Australie ? Tout s’explique avec une idée simple : la lumière se propage <b>en ligne droite</b>.`,
  [T('Objets transparents, translucides, opaques',`<p>Un objet <b>transparent</b> laisse passer la lumière et on voit nettement à travers (vitre, eau limpide). Un objet <b>translucide</b> laisse passer la lumière mais on ne voit pas nettement à travers (verre dépoli, papier calque). Un objet <b>opaque</b> ne laisse pas passer la lumière (carton, bois, métal, corps humain).</p><p>Dans un milieu transparent et homogène, la lumière se propage en <b>ligne droite</b>, très vite : environ <b>300 000 km/s</b>.</p>`),
   T('Ombre propre, ombre portée',`<p>Un objet opaque éclairé par une source présente une partie éclairée et une partie sombre : l’<b>ombre propre</b>. Derrière lui, sur un écran, apparaît une zone non éclairée : l’<b>ombre portée</b>. La source, l’objet et l’ombre portée sont <b>alignés</b>. Quand on rapproche l’objet de la source, l’ombre portée <b>grandit</b>.</p><p>Le Soleil bas sur l’horizon (matin, soir) donne des ombres longues ; à midi, le Soleil est au plus haut et les ombres sont les plus courtes.</p>`),
   T('Jour, nuit et saisons',`<p>La Terre est une boule opaque éclairée par le Soleil : une moitié est éclairée (jour), l’autre est dans l’ombre (nuit). En tournant sur elle-même en 24 h, chaque lieu passe du jour à la nuit : c’est l’<b>alternance jour-nuit</b>.</p><p>L’axe de rotation de la Terre est <b>incliné</b>. Au cours de l’année, pour un observateur en France, le Soleil monte plus ou moins haut dans le ciel et la durée du jour change : en été, Soleil haut et jours longs ; en hiver, Soleil bas et jours courts. Les saisons ne sont <b>pas</b> dues à la distance Terre-Soleil : la Terre est même au plus près du Soleil début janvier !</p>`)],
  [{q:'Un bâton planté au sol est éclairé par le Soleil à 9 h, à midi et à 17 h. Comment évolue son ombre ?',s:['Le matin, le Soleil est bas à l’est : l’ombre est longue, dirigée vers l’ouest.','À midi, le Soleil est au plus haut, au sud : l’ombre est la plus courte, dirigée vers le nord.','En fin d’après-midi, le Soleil est bas à l’ouest : l’ombre s’allonge vers l’est.']}],
  ['Je repère la source de lumière et l’objet opaque.','Je trace des lignes droites depuis la source en frôlant l’objet.','Je place l’ombre propre (sur l’objet) et l’ombre portée (derrière, dans l’alignement).','Pour le jour, la nuit et les saisons, je raisonne avec la rotation de la Terre et l’inclinaison de son axe.'],
  ['Croire que les saisons viennent de la distance au Soleil : elles viennent de l’inclinaison de l’axe de la Terre (hauteur du Soleil et durée du jour).','Placer l’ombre du côté de la source de lumière.','Croire que la nuit est due au fait que le Soleil « s’éteint » ou que la Lune le cache.'],
  ['La lumière se propage en ligne droite, à environ 300 000 km/s.','Source, objet opaque et ombre portée sont alignés.','Jour et nuit : rotation de la Terre en 24 h ; saisons : inclinaison de l’axe de la Terre.']),
 g:mix([sort({'transparent':['une vitre propre','de l’eau limpide','une bouteille en verre incolore','un film plastique alimentaire'],'translucide':['du verre dépoli de salle de bain','une feuille de papier calque','du papier sulfurisé','un abat-jour en tissu fin'],'opaque':['une planche de bois','une plaque de métal','un carton','un livre fermé','un mur de briques']},{q:'« %s » : comment est cet objet vis-à-vis de la lumière ?',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} : objet ${c}. Transparent : on voit nettement à travers ; translucide : la lumière passe mais pas l’image ; opaque : aucune lumière ne passe.`}),3],
  [d=>{if(d<3||Math.random()<.4){const mv=P(['rapproche l’objet de la lampe','éloigne l’objet de la lampe','rapproche l’écran de l’objet','éloigne l’écran de l’objet']);const big=mv==='rapproche l’objet de la lampe'||mv==='éloigne l’écran de l’objet';
      return ch(`Une lampe éclaire un objet opaque ; son ombre portée se forme sur un écran. On ${mv}. L’ombre portée…`,big?'grandit':'rétrécit',[big?'rétrécit':'grandit','garde la même taille','disparaît'],{expl:`Les rayons issus de la lampe s’écartent en ligne droite : plus l’objet est près de la lampe (ou plus l’écran est loin de l’objet), plus l’ombre portée est grande. Ici, elle <b>${big?'grandit':'rétrécit'}</b>.`,hint:'Trace les rayons qui frôlent les bords de l’objet.'});}
    const h=P([2,3,4,5,6]),a=P([10,20,25,50]),k=P([2,3,4]);const D=a*k;
    return num(`Une petite lampe éclaire un carton de <b>${h} cm</b> de haut placé à <b>${a} cm</b> d’elle. L’écran est à <b>${D} cm</b> de la lampe. On admet que la hauteur de l’ombre portée est proportionnelle à la distance lampe-écran. Quelle est la hauteur de l’ombre ?`,h*k,{unit:'cm',expl:`L’écran est ${k} fois plus loin de la lampe que le carton (${D} ÷ ${a} = ${k}) : l’ombre est ${k} fois plus haute, ${h} × ${k} = <b>${h*k} cm</b>.`,hint:'Combien de fois l’écran est-il plus loin que le carton ?'});},2],
  [bank([['Le soir, l’ombre d’un arbre est longue, car…','le Soleil est bas sur l’horizon',['le Soleil est plus loin','la lumière est plus faible','l’arbre a grandi'],'Avec des rayons rasants, l’ombre portée s’allonge.'],
   ['L’alternance du jour et de la nuit s’explique par…','la rotation de la Terre sur elle-même',['la révolution de la Terre autour du Soleil','le passage de la Lune devant le Soleil','le Soleil qui s’éteint la nuit'],'La Terre tourne sur elle-même en 24 h : chaque lieu passe de la moitié éclairée à la moitié dans l’ombre.'],
   ['Les saisons s’expliquent par…','l’inclinaison de l’axe de rotation de la Terre',['la variation de la distance Terre-Soleil','la rotation de la Terre en 24 h','les nuages'],'L’inclinaison de l’axe fait varier la hauteur du Soleil et la durée du jour.',2],
   ['En France, en été, par rapport à l’hiver, le Soleil de midi est…','plus haut dans le ciel, et les jours sont plus longs',['plus bas, et les jours sont plus courts','plus proche de la Terre','à la même hauteur'],'Soleil haut et jours longs : il fait plus chaud.',2],
   ['Début janvier, la Terre est…','au plus près du Soleil, et c’est pourtant l’hiver en France',['au plus loin du Soleil','immobile','à égale distance du Soleil qu’en juillet'],'Preuve que les saisons ne sont pas dues à la distance au Soleil.',3],
   ['Quand il fait jour en France, en Australie (de l’autre côté de la Terre), il fait en général…','nuit',['jour aussi','toujours plus chaud','sombre à cause de la Lune'],'L’Australie est alors sur la moitié non éclairée de la Terre.',2],
   ['La partie sombre d’un objet éclairé, sur l’objet lui-même, est…','l’ombre propre',['l’ombre portée','la pénombre de l’écran','le reflet'],'L’ombre portée est celle qui se forme derrière l’objet, sur un écran ou le sol.'],
   ['La lumière se propage à environ…','300 000 km/s',['340 m/s','300 km/h','3 000 km/s'],'C’est la vitesse de la lumière dans le vide (et presque dans l’air) ; 340 m/s est celle du son.',3]]),3])},

{id:'pc6k',name:'Son : produire, propager, entendre',icon:'🔊',domain:'Signaux',
 refs:[REF6,T6('Signal et information — Transmission de l’information'),T5('thème « Des signaux pour observer et communiquer », signaux sonores (prolongement en 5e)')],
 tip:'Un son, c’est toujours une vibration : cherche ce qui vibre (corde, membrane, cordes vocales) et dans quoi le son se propage.',
 c:C(`Pose la main sur ta gorge et parle : tu sens une vibration. Pince une corde de guitare : elle vibre et on entend une note. Comment un son est-il produit, comment arrive-t-il jusqu’à nos oreilles et comment sert-il à transmettre des informations ?`,
  [T('Produire un son',`<p>Un son est produit par un objet qui <b>vibre</b> : corde de guitare, peau de tambour, membrane de haut-parleur, cordes vocales. Si la vibration s’arrête (on pose la main sur la corde), le son s’arrête.</p><p>Le son se transmet de proche en proche dans un <b>milieu matériel</b> : air, eau, solides. Il ne se propage <b>pas dans le vide</b> : dans l’espace, aucun son ne voyage.</p>`),
   T('Propagation et réception',`<p>Dans l’air, le son se propage à environ <b>340 m/s</b> : beaucoup plus lentement que la lumière (300 000 km/s, presque un million de fois plus vite). C’est pourquoi on voit l’éclair avant d’entendre le tonnerre : chaque seconde d’attente correspond à environ 340 m.</p><p>L’oreille reçoit le son : le <b>tympan</b> se met à vibrer, et le message est transmis au cerveau. Les sons trop forts (concert, casque à fond) peuvent abîmer l’oreille de façon définitive.</p>`),
   T('Des signaux pour transmettre une information',`<p>Un <b>signal</b> transporte une information : signal <b>sonore</b> (sirène, alarme incendie, sifflet de l’arbitre), signal <b>lumineux</b> (feu tricolore, phare, voyant de charge, fibre optique), signal <b>électrique</b> (câble téléphonique ou réseau en cuivre). Une information simple peut être binaire : alarme activée ou non.</p>`)],
  [{q:'Tu entends le tonnerre 3 s après avoir vu l’éclair. À quelle distance est l’orage ?',s:['La lumière de l’éclair arrive presque instantanément.','Le son parcourt environ 340 m chaque seconde : d = 340 × 3.','L’orage est à environ 1 020 m, soit environ 1 km.']}],
  ['Je cherche ce qui vibre (la source du son).','Je vérifie qu’il existe un milieu matériel entre la source et l’oreille.','Pour une distance, j’utilise d = 340 × t (en m, t en s).','Je repère la nature d’un signal : sonore, lumineux ou électrique.'],
  ['Croire que le son se propage dans le vide de l’espace.','Penser que le son et la lumière arrivent en même temps : le son est beaucoup plus lent.','Croire que le son n’existe que dans l’air : il se propage aussi dans l’eau et dans les solides.'],
  ['Un son est produit par une vibration.','Le son a besoin d’un milieu matériel ; il ne se propage pas dans le vide.','Dans l’air, le son va à environ 340 m/s ; la lumière, à environ 300 000 km/s.']),
 g:mix([thunder,3],
  [sort({'signal sonore':['une alarme incendie','le sifflet de l’arbitre','une sirène de pompiers','la sonnerie de fin de cours'],'signal lumineux':['un feu tricolore','le voyant de charge d’un téléphone','la lumière d’un phare','une fibre optique d’internet'],'signal électrique':['le courant dans un câble téléphonique en cuivre','le signal dans un câble réseau en cuivre','le signal envoyé par un capteur relié à une carte programmable']},{q:'« %s » : de quel type de signal s’agit-il ?',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} : ${c}.`}),3],
  [sort({'une corde qui vibre':['une guitare','un violon','une harpe'],'une membrane ou une peau qui vibre':['un tambour','un haut-parleur','un djembé'],'une colonne d’air qui vibre':['une flûte','une trompette','un sifflet'],'des cordes vocales qui vibrent':['la voix d’un chanteur','les pleurs d’un bébé']},{q:'Dans %s, qu’est-ce qui vibre pour produire le son ?',e:(x,c)=>`Dans ${x}, le son est produit par ${c}.`}),2],
  [bank([['Peut-on entendre une explosion dans l’espace, loin de tout objet ?','non, le son ne se propage pas dans le vide',['oui, comme sur Terre','oui, mais plus fort','oui, mais plus tard'],'Le son a besoin d’un milieu matériel (air, eau, solide).',2],
   ['Pourquoi voit-on l’éclair avant d’entendre le tonnerre ?','la lumière va beaucoup plus vite que le son',['l’éclair a lieu avant le tonnerre','le son est arrêté par les nuages','nos yeux sont plus rapides que nos oreilles'],'Ils sont produits en même temps, mais le son n’avance qu’à 340 m/s.'],
   ['Dans l’oreille, quelle partie se met à vibrer en recevant un son ?','le tympan',['la rétine','le cristallin','la cornée'],'Le tympan est une fine membrane qui vibre ; la rétine appartient à l’œil.'],
   ['Le son peut-il se propager dans l’eau ?','oui',['non','seulement dans l’eau salée','seulement s’il fait chaud'],'Les plongeurs entendent les bateaux : le son se propage même plus vite dans l’eau que dans l’air.',2],
   ['Que se passe-t-il si on pose la main sur une corde de guitare qui vibre ?','le son s’arrête',['le son devient plus fort','le son devient plus aigu','rien'],'Sans vibration, plus de son.'],
   {n:'Dans l’air, environ combien de mètres le son parcourt-il en une seconde ?',a:340,u:'m',e:'La vitesse du son dans l’air est d’environ 340 m/s.'},
   ['Écouter de la musique très fort au casque pendant longtemps…','peut abîmer l’oreille de façon définitive',['muscle l’oreille','n’a aucun effet','améliore l’audition'],'Les cellules de l’oreille interne détruites par le bruit ne se réparent pas.',2]]),3])},

{id:'pc6l',name:'Mesurer, expérimenter et raisonner en sciences',icon:'🔬',domain:'Démarche scientifique',
 refs:[REF6,'BO n°25 du 22 juin 2023 — préambule et thème « Matière, mouvement, énergie, information » (variabilité et reproductibilité des mesures, démarche scientifique)'],
 tip:'Dans une expérience, ne fais varier qu’un seul facteur à la fois et garde tous les autres identiques : sinon, tu ne sauras pas lequel a agi.',
 c:C(`Le sucre se dissout-il plus vite dans l’eau chaude ? Pour répondre en scientifique, il ne suffit pas d’avoir une opinion : il faut formuler une hypothèse, la tester par une expérience bien construite, mesurer avec soin et conclure à partir des faits.`,
  [T('La démarche scientifique',`<ol class="lst"><li>Une <b>question</b> (un problème) à partir d’une observation.</li><li>Une <b>hypothèse</b> : une réponse possible, que l’on va tester.</li><li>Une <b>expérience</b> : on ne fait varier qu’<b>un seul facteur</b> à la fois, tous les autres restent identiques ; on prévoit souvent une expérience <b>témoin</b>.</li><li>Des <b>résultats</b> (mesures, observations), présentés dans un tableau ou un graphique.</li><li>Une <b>conclusion</b> : l’hypothèse est validée ou rejetée.</li></ol><p>Si les faits contredisent une idée, ce sont les faits qui l’emportent.</p>`),
   T('Bien mesurer',`<p>Chaque grandeur a son instrument et son unité : longueur (règle, mètre ruban : m), masse (balance : kg), volume (éprouvette graduée : L), température (thermomètre : °C), durée (chronomètre : s). Pour lire un instrument gradué, on cherche d’abord la <b>valeur d’une graduation</b>.</p><p>Une mesure n’est jamais parfaitement identique quand on la répète : c’est la <b>variabilité</b>. On répète donc la mesure, on écarte une valeur aberrante (erreur de manipulation) et on calcule la <b>moyenne</b>. Une expérience est <b>reproductible</b> si on obtient des résultats proches en la refaisant.</p>`)],
  [{q:'Trois mesures de la durée de chute d’une balle : 0,62 s ; 0,58 s ; 0,63 s. Quel résultat retenir ?',s:['Les trois valeurs sont proches : aucune n’est aberrante.','Moyenne : (0,62 + 0,58 + 0,63) ÷ 3 = 1,83 ÷ 3.','On retient 0,61 s.']}],
  ['Je formule la question et une hypothèse.','Je choisis le facteur à faire varier et je liste ceux qui restent identiques.','Je mesure avec l’instrument adapté, plusieurs fois, et je calcule la moyenne.','Je compare les résultats et je conclus sur l’hypothèse.'],
  ['Changer deux facteurs à la fois (température et quantité de sucre) : on ne peut plus conclure.','Ne faire qu’une seule mesure et la croire parfaite.','Confondre hypothèse (idée à tester) et conclusion (ce que montrent les résultats).'],
  ['Un seul facteur varie à la fois ; les autres restent identiques.','Répéter les mesures et calculer la moyenne ; écarter les valeurs aberrantes.','Chaque grandeur a son instrument et son unité.']),
 g:mix([d=>{const EXP=[['si la température de l’eau influence la durée de dissolution d’un morceau de sucre','la température de l’eau',['la masse du morceau de sucre','le volume d’eau','le fait de remuer ou non']],['si la masse d’un pendule influence la durée d’une oscillation','la masse accrochée au fil',['la longueur du fil','l’angle de départ','le lieu de l’expérience']],['si la hauteur de lâcher influence la hauteur du rebond d’une balle','la hauteur de lâcher',['la balle utilisée','la nature du sol','la façon de lâcher la balle']],['si une couche de laine ralentit le refroidissement d’un flacon d’eau chaude','la présence ou non de laine autour du flacon',['la température initiale de l’eau','le volume d’eau','le type de flacon']],['si la quantité de sel dissous modifie la température de solidification de l’eau','la masse de sel dissous',['le volume d’eau','le congélateur utilisé','le récipient']],['si l’inclinaison d’une rampe modifie la vitesse d’une petite voiture en bas de la rampe','l’inclinaison de la rampe',['la voiture utilisée','la longueur parcourue sur la rampe','le revêtement de la rampe']]];
    const [q,v,k]=P(EXP);return ch(`Un élève veut savoir ${q}. Quel facteur doit-il faire varier d’un essai à l’autre ?`,v,k,{expl:`On ne fait varier que le facteur testé, <b>${v}</b> ; tout le reste (${k.join(', ')}) doit rester identique, sinon on ne saurait pas quel facteur a provoqué la différence.`,hint:'Quel facteur est cité dans la question de l’élève ?'});},3],
  [d=>{const n=d===1?3:R(3,5);const base=R(d===1?20:100,d===1?60:900);const vals=[];let s=0;for(let i=0;i<n-1;i++){const v=base+R(-4,4);vals.push(v);s+=v;}
    let last=base+R(-4,4);while((s+last)%n!==0)last++;vals.push(last);s+=last;const div=d===1?1:10;const unit=P(d===1?[['s',' s'],['°C',' °C']]:[['s',' s'],['g',' g'],['cm',' cm'],['mL',' mL']]);
    const show=vals.map(v=>F(rd(v/div))+unit[1]).join(' ; ');const mean=rd(s/n/div);
    return num(`Un groupe répète ${n} fois la même mesure : ${show}. Quelle est la moyenne ?`,mean,{unit:unit[0],expl:`Somme : ${F(rd(s/div))} ; nombre de mesures : ${n}. Moyenne = ${F(rd(s/div))} ÷ ${n} = <b>${F(mean)}${unit[1]}</b>.`,hint:'Additionne les valeurs, puis divise par leur nombre.'});},2],
  [d=>{const base=R(20,80);const vals=[base,base+1,base-1,base+R(0,1)];const out=base*P([2,3])+R(1,5);const all=shuffle([...vals.slice(0,3),out]);
    return ch(`Quatre mesures de la même durée (en s) : ${all.join(' ; ')}. Quelle valeur est aberrante et doit être écartée avant de calculer la moyenne ?`,String(out),all.filter(x=>x!==out).map(String),{expl:`Les valeurs ${all.filter(x=>x!==out).join(', ')} sont proches ; <b>${out}</b> est très éloignée : sans doute une erreur de manipulation.`,hint:'Cherche la valeur très différente des autres.'});},1],
  [d=>{const lo=P([0,10,20,50,100]),step=P([1,2,5]),k=R(1,9);const unit=P([['mL','une éprouvette'],['°C','un thermomètre'],['g','le cadran d’une balance']]);const v=lo+k*step;
    return num(`Sur ${unit[1]}, chaque petite graduation vaut <b>${step} ${unit[0]}</b>. L’indication est à ${k} graduation${k>1?'s':''} au-dessus du trait « ${lo} ${unit[0]} ». Quelle valeur lit-on ?`,v,{unit:unit[0],expl:`${lo} + ${k} × ${step} = <b>${v} ${unit[0]}</b>.`,hint:'Valeur de départ + nombre de graduations × valeur d’une graduation.'});},2],
  [pairs([['masse','une balance'],['volume d’un liquide','une éprouvette graduée'],['température','un thermomètre'],['durée','un chronomètre'],['longueur','une règle graduée ou un mètre ruban']],{q:'Quel instrument mesure la grandeur « %s » ?',rq:'Quelle grandeur mesure-t-on avec %s ?',e:(a,b)=>`Grandeur « ${a} » : on la mesure avec ${b}.`}),2],
  [seq(['poser une question','formuler une hypothèse','réaliser une expérience','noter les résultats','conclure'],{nq:'Dans la démarche scientifique, que fait-on juste après « %s » ?',pq:'Dans la démarche scientifique, que fait-on juste avant « %s » ?',oq:'Remets dans l’ordre les étapes de la démarche scientifique :'}),2],
  [bank([['Une hypothèse est…','une réponse possible à une question, que l’on va tester',['un résultat de mesure','une conclusion certaine','une opinion qu’on ne vérifie pas'],'Elle est validée ou rejetée par l’expérience.'],
   ['Pourquoi répète-t-on une mesure plusieurs fois ?','parce que les mesures varient un peu ; la moyenne est plus fiable',['pour aller plus vite','pour obtenir toujours la même valeur','parce que la première mesure est toujours fausse'],'C’est la variabilité des mesures.',2],
   ['À quoi sert une expérience témoin ?','à comparer avec l’expérience où l’on a modifié un facteur',['à remplacer l’expérience','à prouver qu’on a raison','à mesurer plus vite'],'Le témoin est identique sauf pour le facteur testé.',3],
   ['Si les résultats d’expérience contredisent l’hypothèse, on…','rejette (ou modifie) l’hypothèse',['change les résultats','garde l’hypothèse','refait l’expérience jusqu’à obtenir ce qu’on veut'],'En sciences, les faits l’emportent sur les idées.',2]]),2])}
]);

/* ===================== 5e ===================== */
MQ.add('pc','5',[
{id:'pc5a',name:'Corps purs, mélanges et solutions',icon:'🧂',domain:'Matière',
 refs:[REF5,T5('thème « Organisation et transformations de la matière » : « Décrire la constitution et les états de la matière » (corps pur et mélange, solubilité, miscibilité, composition de l’air)')],
 tip:'Corps pur = une seule espèce chimique. Si l’étiquette liste plusieurs constituants (eau minérale : calcium, magnésium…), c’est un mélange.',
 c:C(`Sur l’étiquette d’une bouteille d’eau minérale, on lit une liste de « sels minéraux ». L’eau du robinet, l’eau minérale, l’eau distillée : est-ce la même chose ? Pour le savoir, il faut distinguer <b>corps pur</b> et <b>mélange</b>.`,
  [T('Espèce chimique, corps pur, mélange',`<p>Une <b>espèce chimique</b> est une substance bien définie (eau, sel, sucre, dioxygène…). Un <b>corps pur</b> ne contient qu’<b>une seule</b> espèce chimique (eau distillée, sucre pur). Un <b>mélange</b> en contient plusieurs (eau minérale, air, jus d’orange).</p><p>Un corps pur se reconnaît à ses <b>températures de changement d’état</b> fixes : l’eau pure se solidifie à 0 °C avec un <b>palier</b> de température ; l’eau salée n’a pas de palier net et commence à geler en dessous de 0 °C.</p><p>Le <b>test au sulfate de cuivre anhydre</b> (poudre blanche qui devient bleue) révèle la présence d’eau.</p>`),
   T('Dissolution, solubilité, saturation',`<p>Une <b>solution</b> est un mélange homogène obtenu en dissolvant un <b>soluté</b> dans un <b>solvant</b>. La masse se conserve : m(solution) = m(solvant) + m(soluté). La <b>solubilité</b> est la masse maximale de soluté que l’on peut dissoudre dans un litre de solvant à une température donnée (environ 360 g/L pour le sel dans l’eau à 20 °C ; environ 2 000 g/L pour le sucre). Au-delà, la solution est <b>saturée</b> : le solide en excès reste au fond.</p><p>Des gaz aussi se dissolvent : le dioxyde de carbone dissous sous pression dans les boissons gazeuses s’échappe à l’ouverture.</p>`),
   T('Miscibilité',`<p>Deux liquides sont <b>miscibles</b> s’ils forment un mélange homogène (eau et alcool, eau et sirop). Ils sont <b>non miscibles</b> s’ils forment deux couches (eau et huile) ; le liquide qui a la plus grande masse pour un même volume est en dessous.</p>`)],
  [{q:'La solubilité du sel dans l’eau est d’environ 360 g/L à 20 °C. On verse 100 g de sel dans 250 mL d’eau. Tout se dissout-il ?',s:['250 mL = 0,25 L.','Masse maximale dissoute : 360 × 0,25 = 90 g.','100 g > 90 g : 10 g de sel restent au fond, la solution est saturée.']}],
  ['Je compte les espèces chimiques : une seule (corps pur) ou plusieurs (mélange).','Je regarde si le mélange est homogène (solution, liquides miscibles) ou hétérogène.','Pour la saturation, je calcule la masse maximale dissoute : solubilité × volume (en L).','J’utilise la conservation de la masse.'],
  ['Croire que « pur » veut dire « bon pour la santé » : l’eau minérale est un mélange, et c’est très bien.','Oublier de convertir les mL en L avant d’utiliser une solubilité en g/L.','Croire qu’un mélange homogène est un corps pur parce qu’on ne voit qu’une phase.'],
  ['Corps pur : une seule espèce chimique ; mélange : plusieurs.','Solubilité : masse maximale dissoute par litre de solvant ; au-delà, solution saturée.','Liquides miscibles : mélange homogène ; non miscibles : plusieurs couches.']),
 g:mix([sort({'corps pur':['l’eau distillée','le sucre en morceaux (saccharose)','le dioxygène d’une bouteille de plongée médicale','le diazote liquide','un fil de cuivre pur'],'mélange':['l’eau minérale','l’air','le jus d’orange','l’eau de mer','le lait','le sirop de menthe dilué','l’eau du robinet']},{q:'« %s » : corps pur ou mélange ?',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} : ${c}${c==='mélange'?' (plusieurs espèces chimiques)':' (une seule espèce chimique)'}.`}),3],
  [d=>{const SOL=[['sel',360],['sucre',2000],['un solide X',P([150,200,250,300])]];const [n,s]=d===1?SOL[0]:P(SOL);const V=P([50,100,200,250,400,500]);const max=rd(s*V/1000);let m=d===1?R(Math.round(max*.3),Math.round(max*1.5)):R(Math.round(max*.5),Math.round(max*1.8));if(Math.abs(m-max)<1)m+=2;const rest=Math.max(0,rd(m-max));
    if(Math.random()<.5)return num(`La solubilité ${n==='un solide X'?'d’un solide X':'du '+n} dans l’eau est d’environ <b>${nf(s)} g/L</b> à 20 °C. Quelle masse maximale peut-on dissoudre dans <b>${V} mL</b> d’eau ?`,max,{unit:'g',expl:`${V} mL = ${F(V/1000)} L ; m(max) = ${nf(s)} × ${F(V/1000)} = <b>${F(max)} g</b>.`,hint:'Convertis le volume en litres.'});
    return num(`La solubilité ${n==='un solide X'?'d’un solide X':'du '+n} dans l’eau est d’environ <b>${nf(s)} g/L</b> à 20 °C. On verse <b>${m} g</b> de ce solide dans <b>${V} mL</b> d’eau et on agite. Quelle masse reste non dissoute ?`,rest,{unit:'g',expl:`Maximum dissous : ${nf(s)} × ${F(V/1000)} = ${F(max)} g. ${rest>0?`Reste : ${m} − ${F(max)} = <b>${F(rest)} g</b> (solution saturée).`:'Tout se dissout : il reste <b>0 g</b>.'}`,hint:'Compare la masse versée et la masse maximale.'});},3],
  [d=>{const w=R(10,50)*10,s=R(5,60);if(Math.random()<.5)return num(`On dissout complètement <b>${s} g</b> de sucre dans <b>${w} g</b> d’eau. Masse de la solution ?`,w+s,{unit:'g',expl:`Conservation de la masse : ${w} + ${s} = <b>${w+s} g</b>.`,hint:'Rien ne disparaît.'});
    return num(`Une solution de sel a une masse de <b>${w+s} g</b>. Elle a été préparée avec <b>${w} g</b> d’eau. Quelle masse de sel a été dissoute ?`,s,{unit:'g',expl:`m(sel) = m(solution) − m(eau) = ${w+s} − ${w} = <b>${s} g</b>.`,hint:'Conservation de la masse.'});},2],
  [sort({'miscibles (mélange homogène)':['l’eau et l’alcool','l’eau et le sirop de grenadine','l’eau et le vinaigre'],'non miscibles (deux couches)':['l’eau et l’huile','l’eau et le white-spirit','le vinaigre et l’huile d’olive']},{q:'« %s » : ces deux liquides sont…',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} : ${c}.`}),2],
  [bank([['Le sulfate de cuivre anhydre, blanc, devient bleu au contact…','de l’eau',['du sel','du dioxygène','de l’huile'],'C’est le test caractéristique de la présence d’eau.'],
   ['L’eau salée commence à geler…','en dessous de 0 °C, sans palier net',['à 0 °C exactement avec un palier','à 100 °C','jamais'],'Un mélange n’a pas de température de changement d’état fixe ; c’est pour cela qu’on sale les routes.',2],
   ['À l’ouverture d’une bouteille de soda, des bulles apparaissent. Ce gaz était…','du dioxyde de carbone dissous dans la boisson',['de l’air entré à l’ouverture','de la vapeur d’eau','du dioxygène fabriqué par le sucre'],'Le CO₂ dissous sous pression s’échappe quand la pression diminue.',2],
   ['Une solution saturée est une solution…','qui ne peut plus dissoudre davantage de soluté',['très colorée','qui contient beaucoup de solvant','qui ne contient pas de soluté'],'Le soluté ajouté en plus reste visible au fond.'],
   ['Un mélange homogène est-il forcément un corps pur ?','non, l’eau salée est homogène mais c’est un mélange',['oui, toujours','oui, s’il est transparent','oui, s’il est liquide'],'Homogène veut dire « une seule phase visible », pas « une seule espèce ».',3],
   ['Comment vérifier qu’un liquide est de l’eau pure ?','il se solidifie à 0 °C avec un palier et bout à 100 °C',['il est transparent','il n’a pas d’odeur','il bleuit le sulfate de cuivre anhydre'],'Le sulfate de cuivre montre la présence d’eau, pas sa pureté ; les températures de changement d’état caractérisent le corps pur.',3]]),2])},

{id:'pc5b',name:'Transformations physiques de la matière',icon:'❄️',domain:'Matière',
 refs:[REF5,T5('« Décrire la constitution et les états de la matière » : changements d’état, conservation de la masse, variation du volume, température de changement d’état, interprétation microscopique')],
 tip:'Lors d’une transformation physique, les particules restent les mêmes : seule leur organisation change. La masse se conserve, le volume peut changer.',
 c:C(`Quand l’eau gèle, elle devient glace ; quand elle bout, elle devient vapeur. Pourtant, c’est toujours de l’eau ! Comment expliquer ces <b>transformations physiques</b> à l’échelle des particules invisibles qui composent la matière ?`,
  [T('Le modèle particulaire',`<p>La matière est constituée de particules minuscules (des <b>molécules</b> pour l’eau). Dans un <b>solide</b>, elles sont <b>rapprochées et ordonnées</b>, elles vibrent sur place. Dans un <b>liquide</b>, elles sont <b>rapprochées et désordonnées</b>, elles glissent les unes sur les autres. Dans un <b>gaz</b>, elles sont <b>éloignées et désordonnées</b>, très agitées.</p><p>Ce modèle explique pourquoi un gaz se comprime (il y a de l’espace entre les particules) et un liquide presque pas.</p>`),
   T('Changements d’état : ce qui se conserve',`<p>Lors d’un changement d’état, les molécules ne changent pas : seule leur disposition change. Donc la <b>masse se conserve</b>. Le <b>volume</b>, lui, varie : 1 L d’eau liquide donne environ 1,09 L de glace (l’eau est une exception : elle prend plus de place à l’état solide) et environ 1 700 L de vapeur à 100 °C.</p><p>Un corps pur change d’état à une <b>température fixe</b> (palier) : eau 0 °C (fusion) et 100 °C (ébullition) ; éthanol : ébullition vers 78 °C ; acide stéarique : fusion vers 69 °C. Ces températures permettent d’<b>identifier</b> un corps pur.</p>`),
   T('Transformation physique ou chimique ?',`<p>Dans une <b>transformation physique</b> (changement d’état, dissolution, broyage), les espèces chimiques restent les mêmes : on peut souvent revenir en arrière. Dans une <b>transformation chimique</b> (combustion, rouille, cuisson d’un gâteau, vinaigre + bicarbonate), de <b>nouvelles espèces</b> apparaissent : changement de couleur, gaz, dépôt solide…</p>`)],
  [{q:'On place 200 g d’eau liquide au congélateur. Quelle est la masse de glace obtenue ? Son volume augmente-t-il ?',s:['La solidification est une transformation physique : les molécules d’eau sont les mêmes.','La masse se conserve : 200 g de glace.','Le volume augmente d’environ 9 % : environ 218 cm³ de glace au lieu de 200 cm³ d’eau.']}],
  ['J’identifie le type de transformation : les espèces chimiques restent-elles les mêmes ?','Si c’est un changement d’état, je le nomme et je décris les particules avant et après.','J’applique la conservation de la masse ; je n’oublie pas que le volume peut changer.','Sur une courbe, je repère le palier pour identifier un corps pur.'],
  ['Croire que la masse change lors d’un changement d’état (« la glace est plus lourde »).','Penser que les molécules grossissent quand on chauffe : c’est l’espace entre elles qui augmente.','Confondre transformation physique (même espèce) et chimique (nouvelles espèces).'],
  ['Solide : particules ordonnées et rapprochées ; liquide : désordonnées et rapprochées ; gaz : désordonnées et éloignées.','Changement d’état : la masse se conserve, le volume varie.','Transformation physique : mêmes espèces chimiques ; transformation chimique : nouvelles espèces.']),
 g:mix([d=>curveQ(d,5),3],
  [sort({'solide':['particules rapprochées et ordonnées, qui vibrent sur place','état où les particules forment un empilement régulier'],'liquide':['particules rapprochées et désordonnées, qui glissent les unes sur les autres','état où les particules restent au contact mais changent de place'],'gaz':['particules éloignées et désordonnées, très agitées','état où il y a beaucoup d’espace entre les particules']},{q:'Modèle particulaire : « %s » décrit quel état ?',e:(x,c)=>`« ${x} » : état ${c}.`}),2],
  [sort({'transformation physique':['la fusion d’un glaçon','la dissolution du sucre dans le thé','l’ébullition de l’eau','la formation de buée sur une vitre','le broyage du poivre','la solidification de la cire fondue'],'transformation chimique':['la combustion d’une bougie','la rouille d’un clou en fer','la cuisson d’un gâteau','l’effervescence vinaigre + bicarbonate','la combustion du gaz de la cuisinière']},{q:'« %s » : transformation physique ou chimique ?',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} : ${c}${c==='transformation physique'?' (mêmes espèces chimiques avant et après)':' (de nouvelles espèces chimiques apparaissent)'}.`}),3],
  [d=>{const m=R(d===1?5:11,d===1?50:999);const t=P(['se solidifie entièrement','fond entièrement','se vaporise entièrement dans un récipient fermé']);const s=P(['d’eau','de cire','d’éthanol']);
    return num(`Dans un récipient fermé, ${nf(m)} g ${s} ${t}. Quelle est la masse ${s} après la transformation ?`,m,{unit:'g',expl:`Changement d’état = transformation physique : les particules sont les mêmes, la <b>masse se conserve</b> (${nf(m)} g). Seul le volume change.`,hint:'Que devient la masse lors d’un changement d’état ?'});},1],
  [d=>{const V=P([100,200,500,1000,1500]);const vg=Math.round(V*1.09);
    return ch(`On congèle <b>${nf(V)} mL</b> d’eau liquide. On sait que l’eau augmente d’environ 9 % de volume en gelant. Quel est environ le volume de glace obtenu ?`,`environ ${nf(vg)} cm³`,[`${nf(V)} cm³ exactement`,`environ ${nf(Math.round(V*0.91))} cm³`,`environ ${nf(V*9)} cm³`],{expl:`9 % de ${nf(V)} = ${F(rd(V*0.09))} ; ${nf(V)} + ${F(rd(V*0.09))} ≈ <b>${nf(vg)} cm³</b>. La masse, elle, ne change pas.`,hint:'Volume + 9 %.'});},2],
  [d=>{const S=[['l’eau','fusion',0],['l’eau','ébullition',100],['l’éthanol','ébullition',78],['l’acide stéarique','fusion',69],['le cyclohexane','ébullition',81],['l’étain','fusion',232]];const [n,ty,th]=P(S);const others=S.filter(x=>x[0]!==n).map(x=>x[0]);
    return ch(`Un liquide inconnu présente un palier d’${ty} à <b>${th} °C</b>. Données : eau (fusion 0 °C, ébullition 100 °C) ; éthanol (ébullition 78 °C) ; acide stéarique (fusion 69 °C) ; cyclohexane (ébullition 81 °C) ; étain (fusion 232 °C). De quel corps pur s’agit-il ?`.replace('Un liquide inconnu','Un corps pur inconnu').replace('palier d’ébullition','palier d’ébullition').replace('palier d’fusion','palier de fusion'),n,others,{expl:`Chaque corps pur a ses températures de changement d’état. Un palier d’${ty==='fusion'?'fusion':'ébullition'} à ${th} °C correspond ${au(n).replace(/^(au |à )/,'$1<b>')}</b>.`.replace('d’fusion','de fusion'),hint:'Compare la température du palier aux données.'});},2],
  [bank([['Quand on chauffe un gaz, ses molécules…','s’agitent davantage et s’écartent',['grossissent','se multiplient','disparaissent'],'Les molécules ne changent pas de taille ; leur agitation et l’espace entre elles augmentent.',2],
   ['Pourquoi peut-on comprimer un gaz mais presque pas un liquide ?','dans un gaz, les particules sont éloignées les unes des autres',['les particules d’un gaz sont plus petites','un gaz n’a pas de masse','un liquide n’a pas de particules'],'Dans un liquide, les particules sont au contact : il n’y a presque pas d’espace à réduire.',2],
   ['Lors de la fusion d’un glaçon, les molécules d’eau…','restent les mêmes, mais se désordonnent',['se transforment en d’autres molécules','disparaissent','fondent elles-mêmes'],'Une molécule ne fond pas : c’est l’organisation de l’ensemble qui change.',2],
   ['La masse d’un glaçon qui fond…','reste la même',['augmente','diminue','devient nulle'],'Conservation de la masse lors d’un changement d’état.'],
   ['Lors de la solidification de l’eau, son volume…','augmente',['diminue','ne change pas','devient nul'],'L’eau est une exception : la glace occupe plus de place que l’eau liquide (la glace flotte).',2]]),2])},

{id:'pc5c',name:'Masse volumique et identification d’un matériau',icon:'🪨',domain:'Matière',
 refs:[REF5,T5('« Décrire la constitution et les états de la matière » : masse volumique, relation m = ρ × V ; repères de progressivité : proportionnalité masse-volume dès la 5e, grandeur quotient introduite progressivement à partir de la 4e')],
 tip:'ρ = m ÷ V : masse en grammes et volume en cm³ donnent des g/cm³. Compare ensuite avec le tableau des valeurs pour reconnaître le matériau.',
 c:C(`Un bijou doré est-il en or massif ou en laiton ? Les deux brillent de la même façon. Mais pour un même volume, l’or a une masse bien plus grande ! La masse d’un centimètre cube de matière permet d’identifier un matériau : c’est la <b>masse volumique</b>.`,
  [T('Proportionnalité entre masse et volume',`<p>Pour un même matériau, la masse est <b>proportionnelle</b> au volume : 1 cm³ d’aluminium a une masse de 2,7 g, 2 cm³ ont une masse de 5,4 g, 10 cm³ une masse de 27 g. Le coefficient de proportionnalité est la masse d’<b>un</b> centimètre cube : c’est la <b>masse volumique</b>, notée ρ (« rhô »).</p><p><b>ρ = m ÷ V</b>, donc m = ρ × V et V = m ÷ ρ. Si m est en g et V en cm³, ρ est en <b>g/cm³</b> (ou g/mL). 1 g/cm³ = 1 kg/L = 1 000 kg/m³ = 1 000 g/L.</p>`),
   T('Quelques valeurs pour identifier un matériau',`<table class="ptable"><tr><th>Matériau</th><th>ρ (g/cm³)</th></tr><tr><td>éthanol</td><td>0,79</td></tr><tr><td>huile de tournesol</td><td>0,92</td></tr><tr><td>glace</td><td>0,92</td></tr><tr><td>eau liquide</td><td>1,00</td></tr><tr><td>aluminium</td><td>2,70</td></tr><tr><td>fer</td><td>7,87</td></tr><tr><td>cuivre</td><td>8,96</td></tr><tr><td>plomb</td><td>11,35</td></tr><tr><td>or</td><td>19,3</td></tr></table><p>Un objet plein <b>flotte</b> sur un liquide si sa masse volumique est plus petite que celle du liquide : la glace (0,92) flotte sur l’eau (1,00), le fer (7,87) coule.</p>`)],
  [{q:'Un cube de métal a une masse de 54 g et un volume de 20 cm³. Quel est ce métal ?',s:['Je calcule la masse volumique : ρ = m ÷ V = 54 ÷ 20.','ρ = 2,7 g/cm³.','Dans le tableau, 2,7 g/cm³ correspond à l’aluminium.']},
   {q:'Quelle est la masse de 250 mL d’huile (ρ = 0,92 g/mL) ?',s:['m = ρ × V.','m = 0,92 × 250 = 230.','La masse de l’huile est 230 g.']}],
  ['Je mesure la masse (balance) et le volume (éprouvette, par déplacement d’eau pour un solide).','Je calcule ρ = m ÷ V en vérifiant les unités (g et cm³ → g/cm³).','Je compare au tableau de valeurs pour identifier le matériau.','Pour trouver m ou V, j’utilise m = ρ × V ou V = m ÷ ρ.'],
  ['Calculer V ÷ m au lieu de m ÷ V.','Mélanger les unités : une masse en kg avec un volume en cm³.','Croire qu’un objet flotte parce qu’il est « léger » : un gros tronc d’arbre flotte, une petite bille d’acier coule.'],
  ['La masse d’un matériau est proportionnelle à son volume.','ρ = m ÷ V ; eau : 1 g/cm³ = 1 000 kg/m³.','La masse volumique permet d’identifier un matériau et de prévoir s’il flotte.']),
 g:mix([d=>{const [n,rho]=d===1?P(MET.slice(0,4)):P(MET);const V=d===1?P([2,5,10,20]):R(3,60);const m=rd(rho*V,4);
    return num(`Un objet plein en métal a une masse de <b>${F(m)} g</b> et un volume de <b>${V} cm³</b>. Calcule sa masse volumique en g/cm³.`,rho,{unit:'g/cm³',expl:`ρ = m ÷ V = ${F(m)} ÷ ${V} = <b>${F(rho)} g/cm³</b> : c’est la valeur ${duM(n)}.`,hint:'ρ = m ÷ V.'});},3],
  [d=>{const i=R(0,MET.length-1);const [n,rho]=MET[i];const V=R(4,50);const m=rd(rho*V,4);const near=MET.filter(x=>x[0]!==n).sort((a,b)=>Math.abs(a[1]-rho)-Math.abs(b[1]-rho)).slice(0,3).map(x=>x[0]);
    return ch(`Un échantillon de métal a une masse de <b>${F(m)} g</b> pour un volume de <b>${V} cm³</b>. Données (g/cm³) : ${tableMet()}. De quel métal s’agit-il ?`,n,near,{expl:`ρ = ${F(m)} ÷ ${V} = ${F(rho)} g/cm³ : c’est <b>${artM(n)}</b>.`,hint:'Calcule ρ puis cherche-le dans les données.'});},3],
  [d=>{const [n,rho]=P(LIQ);const V=P([50,100,150,200,250,500,750,1000]);const m=rd(rho*V);
    if(Math.random()<.5)return num(`Quelle est la masse de <b>${V} mL</b> ${de(n)} (ρ = ${F(rho)} g/mL) ?`,m,{unit:'g',expl:`m = ρ × V = ${F(rho)} × ${V} = <b>${F(m)} g</b>.`,hint:'m = ρ × V.'});
    return ch(`Quelle est la masse de <b>${V} mL</b> ${de(n)} (ρ = ${F(rho)} g/mL) ?`,`${F(m)} g`,[`${F(rd(V/rho,2))} g`,`${F(rd(m/1000,4))} g`,`${V} g`,`${F(rd(rho+V,2))} g`],{expl:`m = ρ × V = ${F(rho)} × ${V} = <b>${F(m)} g</b>. (Diviser V par ρ serait une erreur de formule.)`,hint:'m = ρ × V.'});},2],
  [d=>{if(d<3)return vrho(d);const [n,rho]=P(MET.slice(0,5));const V=R(2,40);const m=rd(rho*V,4);
    return num(`Une pièce ${de(n)} (ρ = ${F(rho)} g/cm³) a une masse de <b>${F(m)} g</b>. Quel est son volume ?`,V,{unit:'cm³',expl:`V = m ÷ ρ = ${F(m)} ÷ ${F(rho)} = <b>${V} cm³</b>.`,hint:'V = m ÷ ρ.'});},2],
  [d=>{const [n,rho]=P([...MET,...LIQ]);const k=P(['kg/m³','g/L','kg/L']);const res=k==='kg/L'?rho:rd(rho*1000);
    return num(`La masse volumique ${duM(n)} est ${F(rho)} g/cm³. Exprime-la en <b>${k}</b>.`,res,{unit:k,expl:k==='kg/L'?`1 g/cm³ = 1 kg/L (1 L = 1 000 cm³ et 1 kg = 1 000 g) : <b>${F(res)} kg/L</b>.`:`1 g/cm³ = 1 000 ${k} : ${F(rho)} × 1 000 = <b>${F(res)} ${k}</b>.`,hint:'1 g/cm³ = 1 kg/L = 1 000 kg/m³ = 1 000 g/L.'});},2],
  [d=>{const OBJ=[['un glaçon',0.92],['un bouchon de liège',0.24],['une bille d’acier',7.87],['une pièce en aluminium',2.7],['une bougie en paraffine',0.9],['un caillou de granite',2.7],['une bague en or',19.3],['un morceau de bois de pin sec',0.5]];const [o,r]=P(OBJ);const [l,rl]=P([['l’eau',1],['l’huile de tournesol',0.92],['l’éthanol',0.79]]);
    if(Math.abs(r-rl)<0.03)return ch(`${o.charAt(0).toUpperCase()+o.slice(1)} (ρ ≈ ${F(r)} g/cm³) est déposé dans l’eau (ρ = 1 g/cm³). Il…`,r<1?'flotte':'coule',[r<1?'coule':'flotte','reste exactement au milieu','se dissout'],{expl:`Un objet plein flotte si sa masse volumique est inférieure à celle du liquide : ${F(r)} ${r<1?'<':'>'} 1, il <b>${r<1?'flotte':'coule'}</b>.`});
    const f=r<rl;return ch(`${o.charAt(0).toUpperCase()+o.slice(1)} (ρ ≈ ${F(r)} g/cm³) est déposé dans ${l} (ρ = ${F(rl)} g/cm³). Il…`,f?'flotte':'coule',[f?'coule':'flotte','reste exactement au milieu','se dissout'],{expl:`Un objet plein flotte si sa masse volumique est inférieure à celle du liquide : ${F(r)} ${f?'<':'>'} ${F(rl)}, il <b>${f?'flotte':'coule'}</b>.`,hint:'Compare les deux masses volumiques.'});},2],
  [bank([['1 L d’eau a une masse d’environ…','1 kg',['1 g','100 g','10 kg'],'ρ(eau) = 1 g/mL : 1 000 mL ont une masse de 1 000 g = 1 kg.'],
   ['Quelle formule donne la masse volumique ?','ρ = m ÷ V',['ρ = V ÷ m','ρ = m × V','ρ = m + V'],'La masse volumique est la masse d’une unité de volume.'],
   ['Un kilogramme de plomb et un kilogramme de plumes…','ont la même masse mais pas le même volume',['ont le même volume','n’ont pas la même masse','ont la même masse volumique'],'Même masse ; les plumes occupent un volume beaucoup plus grand.',2],
   ['La glace flotte sur l’eau liquide parce que…','sa masse volumique (0,92 g/cm³) est plus petite que celle de l’eau',['elle est plus froide','elle contient de l’air','elle est plus lourde'],'Pour un même volume, la glace a une masse plus petite que l’eau.',2],
   ['Une bague dorée de 2 cm³ a une masse de 17 g. Est-elle en or massif (19,3 g/cm³) ?','non, ρ = 8,5 g/cm³, bien moins que l’or',['oui, elle brille','oui, 17 g c’est lourd','on ne peut pas savoir'],'17 ÷ 2 = 8,5 g/cm³ : cela correspond plutôt à du laiton.',3]]),1])},

{id:'pc5d',name:'Atomes et molécules : premiers modèles',icon:'⚛️',domain:'Constitution de la matière',
 refs:[REF5,T5('« Décrire et expliquer des transformations chimiques » : molécules, atomes, formules chimiques (dioxygène, dihydrogène, diazote, eau, dioxyde de carbone, méthane, protoxyde d’azote) ; repères : modèle particulaire dès la 5e')],
 tip:'Dans une formule, le petit chiffre en bas compte les atomes de l’élément juste devant ; pas de chiffre signifie un seul atome.',
 c:C(`Une goutte d’eau contient environ 1 600 milliards de milliards de molécules ! Chacune est formée de trois atomes. Les chimistes utilisent des <b>modèles</b> et des <b>formules</b> pour décrire ces particules invisibles.`,
  [T('Atomes et molécules',`<p>Toute la matière est formée d’<b>atomes</b>, extrêmement petits. Chaque sorte d’atome a un nom et un <b>symbole</b> : H (hydrogène), O (oxygène), C (carbone), N (azote). Une <b>molécule</b> est un assemblage d’atomes liés entre eux. Dans les modèles moléculaires, on représente par convention H en blanc, C en noir, O en rouge et N en bleu.</p><p>La <b>formule</b> d’une molécule indique les atomes qui la composent et leur nombre (en indice) : H₂O = 2 atomes d’hydrogène + 1 atome d’oxygène ; CO₂ = 1 C + 2 O ; CH₄ = 1 C + 4 H ; O₂, H₂, N₂ = 2 atomes identiques ; N₂O (protoxyde d’azote) = 2 N + 1 O.</p>`),
   T('Ce que le modèle explique',`<p>Lors d’une <b>transformation physique</b> (changement d’état, dissolution), les molécules restent les mêmes : la glace, l’eau liquide et la vapeur sont toutes formées de molécules H₂O. Lors d’une <b>transformation chimique</b>, les atomes des molécules de départ (<b>réactifs</b>) se réorganisent pour former de nouvelles molécules (<b>produits</b>) ; les atomes, eux, sont conservés. Exemple : la combustion du méthane dans le dioxygène produit du dioxyde de carbone et de l’eau.</p>`)],
  [{q:'Combien d’atomes y a-t-il dans 3 molécules de dioxyde de carbone CO₂ ?',s:['Une molécule CO₂ contient 1 atome de carbone et 2 atomes d’oxygène, soit 3 atomes.','Pour 3 molécules : 3 atomes de carbone et 6 atomes d’oxygène.','Total : 9 atomes.']}],
  ['Je lis la formule élément par élément.','Le chiffre en indice s’applique à l’atome juste devant ; pas d’indice = 1 atome.','Pour plusieurs molécules, je multiplie le nombre d’atomes par le nombre de molécules.','Je vérifie : en transformation physique, les molécules ne changent pas ; en transformation chimique, les atomes se réorganisent.'],
  ['Lire CO₂ comme « 2 atomes de carbone » : le 2 concerne l’oxygène.','Confondre atome et molécule : O₂ est une molécule formée de deux atomes d’oxygène.','Croire que les molécules fondent ou grossissent lors d’un changement d’état.'],
  ['La matière est formée d’atomes ; une molécule est un assemblage d’atomes.','La formule indique la nature et le nombre d’atomes : H₂O, CO₂, O₂, CH₄, N₂.','Transformation physique : mêmes molécules ; transformation chimique : les atomes se réorganisent.']),
 g:mix([d=>{const MOL=[['l’eau',{H:2,O:1}],['le dioxygène',{O:2}],['le dihydrogène',{H:2}],['le diazote',{N:2}],['le dioxyde de carbone',{C:1,O:2}],['le méthane',{C:1,H:4}],['le protoxyde d’azote',{N:2,O:1}],['le monoxyde de carbone',{C:1,O:1}],['l’ammoniac',{N:1,H:3}],['l’éthanol',{C:2,H:6,O:1}],['le propane',{C:3,H:8}],['le glucose',{C:6,H:12,O:6}]];
    const ORD=['C','H','N','O'];const fm=c=>ORD.filter(e=>c[e]).map(e=>e+sub(c[e])).join('').replace('NH₃','NH₃');const NAME={H:'hydrogène',O:'oxygène',C:'carbone',N:'azote'};
    const fix=(n,c)=>n==='l’ammoniac'?'NH₃':n==='l’éthanol'?'C₂H₆O':n==='le protoxyde d’azote'?'N₂O':n==='l’eau'?'H₂O':fm(c);
    const pool=d===1?MOL.slice(0,7):MOL;const [n,c]=P(pool);const f=fix(n,c);const tot=Object.values(c).reduce((a,b)=>a+b,0);const r=Math.random();
    if(r<.3)return num(`Combien d’atomes au total contient une molécule ${de(n.replace(/^(le |l’)/,''))} <b>${f}</b> ?`,tot,{expl:`${Object.entries(c).map(([e,k])=>`${k} atome${k>1?'s':''} ${de(NAME[e])}`).join(' + ')} = <b>${tot} atomes</b>.`,hint:'Additionne les indices (pas d’indice = 1).'});
    if(r<.6){const els=Object.keys(c);const e=P(els);const k=d===1?R(1,3):R(2,10);return num(`Combien d’atomes <b>${de(NAME[e])}</b> y a-t-il dans <b>${k}</b> molécule${k>1?'s':''} ${de(n.replace(/^(le |l’)/,''))} <b>${f}</b> ?`,k*c[e],{expl:`Une molécule ${f} contient ${c[e]} atome${c[e]>1?'s':''} ${de(NAME[e])} ; ${k} × ${c[e]} = <b>${k*c[e]}</b>.`,hint:'Nombre de molécules × nombre d’atomes par molécule.'});}
    // formule à partir de la composition
    const els=Object.keys(c);const swap={...c};if(els.length===2){swap[els[0]]=c[els[1]];swap[els[1]]=c[els[0]];}
    const bads=[fm(swap),fm({...c,[els[0]]:c[els[0]]+1}),fm(Object.fromEntries(Object.entries(c).map(([e,k])=>[e,k===1?2:1])))].filter(x=>x!==f);
    if(bads.length<1)bads.push(fm({...c,[els[0]]:c[els[0]]+2}));
    return ch(`Une molécule contient ${Object.entries(c).map(([e,k])=>`${k} atome${k>1?'s':''} ${de(NAME[e])}`).join(' et ')}. Quelle est sa formule ?`,f,bads,{expl:`On écrit le symbole de chaque atome suivi, en indice, de son nombre (rien si 1) : <b>${f}</b> (${n}).`,hint:'Symboles : H, O, C, N.'});},5],
  [pairs([['H','hydrogène'],['O','oxygène'],['C','carbone'],['N','azote']],{q:'Quel élément a pour symbole « %s » ?',rq:'Quel est le symbole de l’atome %s ?',e:(a,b)=>`Le symbole ${a} désigne l’atome ${b}.`}),1],
  [pairs([['H₂O','l’eau'],['O₂','le dioxygène'],['CO₂','le dioxyde de carbone'],['CH₄','le méthane'],['N₂','le diazote'],['H₂','le dihydrogène'],['N₂O','le protoxyde d’azote']],{q:'Quelle molécule a pour formule %s ?',rq:'Quelle est la formule chimique de cette espèce : %s ?',e:(a,b)=>`${a} est la formule ${du(b)}.`}),2],
  [bank([['Une molécule est…','un assemblage d’atomes liés entre eux',['un atome très gros','un mélange de corps purs','une espèce chimique visible au microscope'],'Exemple : H₂O est formée de 3 atomes liés.'],
   ['Lors de l’ébullition de l’eau, les molécules d’eau…','restent des molécules H₂O, elles s’éloignent les unes des autres',['se cassent en atomes d’hydrogène et d’oxygène','deviennent des molécules d’air','grossissent'],'Transformation physique : les molécules ne changent pas.',2],
   ['Lors d’une transformation chimique…','les atomes se réorganisent pour former de nouvelles molécules',['les atomes disparaissent','de nouveaux atomes sont créés','les molécules restent les mêmes'],'Les atomes sont conservés, ce sont les molécules qui changent.',2],
   ['Dans un modèle moléculaire, une boule rouge représente par convention un atome…','d’oxygène',['d’hydrogène','de carbone','d’azote'],'H blanc, C noir, O rouge, N bleu.',2],
   ['O₂ et O sont-ils la même chose ?','non, O est un atome et O₂ une molécule de deux atomes d’oxygène',['oui, ce sont deux écritures du même atome','non, O₂ contient deux molécules','non, O est une molécule et O₂ un atome'],'Le dioxygène de l’air est formé de molécules O₂.',3],
   ['La combustion du méthane CH₄ dans le dioxygène produit…','du dioxyde de carbone et de l’eau',['du méthane et de l’eau','du dioxygène et du carbone','de l’azote'],'Les atomes C, H et O se réorganisent en CO₂ et H₂O.',3]]),2])},

{id:'pc5e',name:'Mouvement et vitesse',icon:'🏎️',domain:'Mouvement',
 refs:[REF5,T5('thème « Mouvement et interactions » : « Caractériser un mouvement » (relation vitesse-distance-durée, mouvements uniformes ou non, relativité du mouvement)')],
 tip:'Pour passer de m/s à km/h, multiplie par 3,6 ; pour passer de km/h à m/s, divise par 3,6.',
 c:C(`Sur l’autoroute, la vitesse est limitée à 130 km/h ; Usain Bolt a couru le 100 m à une vitesse moyenne de plus de 10 m/s. Qui va le plus vite ? Pour comparer, il faut savoir <b>calculer</b> et <b>convertir</b> une vitesse, et décrire précisément un <b>mouvement</b>.`,
  [T('Caractériser un mouvement',`<p>Un mouvement se décrit <b>par rapport à</b> un objet de référence : un passager est immobile par rapport au train, en mouvement par rapport au quai. On précise la <b>trajectoire</b> (rectiligne, circulaire, curviligne) et l’évolution de la vitesse : <b>uniforme</b> (constante), <b>accéléré</b> ou <b>ralenti</b>. La vitesse a une <b>valeur</b>, mais aussi une <b>direction</b> et un <b>sens</b> : une voiture qui tourne à vitesse constante change de direction, donc sa vitesse change.</p>`),
   T('Calculer et convertir',`<p><b>v = d ÷ t</b>, donc <b>d = v × t</b> et <b>t = d ÷ v</b>. Unités : m/s (d en m, t en s) ou km/h (d en km, t en h).</p><p>Conversion : 1 m/s, c’est 3 600 m en 1 h, soit 3,6 km/h. Donc <b>m/s × 3,6 = km/h</b> et <b>km/h ÷ 3,6 = m/s</b>. Exemple : 10 m/s = 36 km/h ; 90 km/h = 25 m/s. Ordres de grandeur : marcheur 1,4 m/s ≈ 5 km/h ; son dans l’air 340 m/s ; lumière 300 000 km/s.</p>`)],
  [{q:'Usain Bolt : 100 m en 9,58 s. Est-il plus rapide qu’une voiture en ville à 50 km/h ?',s:['v = d ÷ t = 100 ÷ 9,58 ≈ 10,4 m/s.','Conversion : 10,4 × 3,6 ≈ 37,6 km/h.','37,6 km/h < 50 km/h : la voiture va plus vite.']},
   {q:'Un train roule à 240 km/h pendant 1 h 30 min. Quelle distance parcourt-il ?',s:['1 h 30 min = 1,5 h.','d = v × t = 240 × 1,5.','d = 360 km.']}],
  ['Je précise l’objet de référence et je décris la trajectoire.','Je choisis la bonne relation : v = d ÷ t, d = v × t ou t = d ÷ v.','Je vérifie la cohérence des unités (m et s, ou km et h) et je convertis si besoin (× 3,6 ou ÷ 3,6).','Je contrôle l’ordre de grandeur du résultat.'],
  ['Multiplier par 3,6 pour passer de km/h à m/s (c’est l’inverse).','Écrire 1 h 30 min = 1,3 h au lieu de 1,5 h.','Croire qu’une vitesse constante en valeur signifie forcément un mouvement rectiligne.'],
  ['v = d ÷ t ; d = v × t ; t = d ÷ v.','m/s × 3,6 = km/h ; km/h ÷ 3,6 = m/s.','Un mouvement se décrit par rapport à une référence : trajectoire et évolution de la vitesse.']),
 g:mix([vit5,7],
  [d=>{const kind=P(['uniforme','accéléré','ralenti']);const s=R(2,6),k=R(1,3);let gaps=[];for(let i=0;i<4;i++)gaps.push(kind==='uniforme'?s:kind==='accéléré'?s+i*k:s+(3-i)*k);const pos=[0];gaps.forEach(g=>pos.push(pos[pos.length-1]+g));
    const L={uniforme:'rectiligne uniforme',accéléré:'rectiligne accéléré',ralenti:'rectiligne ralenti'};return ch(`Chronophotographie d’un palet sur une table (une image toutes les 40 ms, points alignés) : positions ${pos.map(x=>x+' cm').join(' ; ')}. Le mouvement est…`,L[kind],Object.values(L).filter(x=>x!==L[kind]).concat(['circulaire uniforme']),{expl:`Points alignés : rectiligne. Écarts : ${gaps.join(' ; ')} cm, ${kind==='uniforme'?'égaux : uniforme':kind==='accéléré'?'croissants : accéléré':'décroissants : ralenti'}.`,hint:'Regarde la forme de la trajectoire puis les écarts.'});},2],
  [bank([['Une voiture prend un rond-point à 30 km/h constants. Sa vitesse…','change de direction, donc le mouvement n’est pas uniforme en ligne droite',['ne change pas du tout','augmente','est nulle'],'La valeur reste 30 km/h, mais la direction change : mouvement circulaire uniforme.',3],
   ['Un passager assis dans un TGV qui roule est immobile…','par rapport à son siège',['par rapport aux rails','par rapport à une vache dans un pré','dans tous les cas'],'Le mouvement est relatif : il faut toujours préciser la référence.'],
   ['1 h 15 min s’écrit en heures décimales…','1,25 h',['1,15 h','1,5 h','1,75 h'],'15 min = 15 ÷ 60 h = 0,25 h.',2],
   ['Pour passer de km/h à m/s, on…','divise par 3,6',['multiplie par 3,6','multiplie par 1 000','divise par 60'],'90 km/h ÷ 3,6 = 25 m/s.'],
   ['La vitesse de la lumière est environ…','300 000 km/s',['340 m/s','300 000 km/h','3 000 m/s'],'C’est près d’un million de fois la vitesse du son dans l’air.',2]]),2])},

{id:'pc5f',name:'Actions mécaniques et interactions',icon:'🤜',domain:'Interactions',
 refs:[REF5,T5('thème « Mouvement et interactions » : actions de contact et à distance, diagramme objet-interaction ; repères : interactions décrites dès le début du cycle 4, modélisées par des forces si possible dès la 4e')],
 tip:'Pour un diagramme objet-interaction, mets l’objet étudié au centre, puis relie-le à tous les objets qui le touchent (trait plein) et à ceux qui agissent à distance (pointillés).',
 c:C(`Un ballon posé sur le sol ne bouge pas ; pourtant, la Terre l’attire vers le bas. Qu’est-ce qui l’empêche de tomber ? Pour répondre, on recense toutes les <b>actions mécaniques</b> qui s’exercent sur un objet et on les représente.`,
  [T('Interactions de contact et à distance',`<p>Une <b>action mécanique</b> est exercée par un acteur sur un receveur. Elle peut être <b>de contact</b> (localisée sur une petite zone ou répartie sur une surface : le sol sous le ballon, l’eau sous un bateau) ou <b>à distance</b> (l’attraction de la Terre, appelée <b>pesanteur</b>, l’action d’un aimant ou d’un objet électrisé).</p><p>Une action est toujours réciproque : si la Terre attire le ballon, le ballon attire aussi la Terre. On parle d’<b>interaction</b>.</p>`),
   T('Le diagramme objet-interaction',`<p>On place l’<b>objet étudié</b> au centre, entouré des objets qui interagissent avec lui. Une interaction de contact est représentée par un <b>trait plein</b>, une interaction à distance par un <b>trait pointillé</b>. Exemple : ballon posé au sol → ballon–sol (contact) et ballon–Terre (distance).</p><p>Effets d’une action : mettre en mouvement, modifier la vitesse (valeur ou direction) ou déformer. Si un objet reste immobile, les actions qu’il subit <b>se compensent</b>. Plus tard (4e), chaque action sera modélisée par une <b>force</b>, mesurée en <b>newtons (N)</b> avec un dynamomètre.</p>`)],
  [{q:'Une lampe est suspendue au plafond par un fil. Fais l’inventaire des actions sur la lampe.',s:['Objet étudié : la lampe.','Objets qui la touchent : le fil (action de contact, il la retient vers le haut).','Action à distance : la Terre (elle l’attire vers le bas). Les deux actions se compensent : la lampe reste immobile.']}],
  ['Je choisis l’objet étudié (le receveur).','Je liste les objets qui le touchent : interactions de contact.','J’ajoute les interactions à distance (Terre, aimant…).','Je représente le diagramme objet-interaction et je décris les effets.'],
  ['Oublier l’action de la Terre, toujours présente sur Terre.','Compter l’air ou des objets qui ne touchent pas l’objet comme actions de contact.','Croire qu’un objet immobile ne subit aucune action.'],
  ['Action de contact : acteur et receveur se touchent ; action à distance : non.','Diagramme objet-interaction : trait plein pour le contact, pointillé pour la distance.','Une interaction est réciproque ; un objet immobile subit des actions qui se compensent.']),
 g:mix([d=>{const SC=[['un livre posé sur une table',['la table'],['la Terre']],['une lampe suspendue au plafond par un fil',['le fil'],['la Terre']],['une boule de pétanque en train de tomber (on néglige l’air)',[],['la Terre']],['un ballon de foot en plein vol (on néglige l’air)',[],['la Terre']],['une balle de tennis au moment où la raquette la frappe (on néglige l’air)',['la raquette'],['la Terre']],['une luge tirée par une corde sur la neige',['la corde','la neige'],['la Terre']],['un bateau qui flotte immobile sur un lac',['l’eau'],['la Terre']],['une pomme accrochée à une branche',['la branche'],['la Terre']],['un skieur qui descend une piste (on néglige l’air)',['la piste'],['la Terre']],['un trombone en acier suspendu à un fil, attiré par un aimant proche qui ne le touche pas',['le fil'],['la Terre','l’aimant']],['un wagon tiré par une locomotive sur des rails (on néglige l’air)',['la locomotive','les rails'],['la Terre']]];
    const [s,c,a]=P(SC);const r=Math.random();
    if(r<.35)return num(`Combien d’<b>actions de contact</b> s’exercent sur ${s} ?`,c.length,{expl:`Objets qui touchent l’objet étudié : ${c.length?c.join(', '):'aucun'} → <b>${c.length}</b>. À distance : ${a.join(' et ')}.`,hint:'Compte seulement les objets qui le touchent.'});
    if(r<.6)return num(`Combien d’actions mécaniques au total (contact et distance) s’exercent sur ${s} ?`,c.length+a.length,{expl:`Contact : ${c.length?c.join(', '):'aucune'} ; à distance : ${a.join(', ')}. Total : <b>${c.length+a.length}</b>.`,hint:'N’oublie pas la Terre.'});
    if(c.length&&r<.85){const g=P(c);const others=['la Terre','l’air','le Soleil','la table','le fil','le sol','la main'].filter(x=>!c.includes(x)&&x!==g);return ch(`Parmi ces acteurs, lequel exerce une action <b>de contact</b> sur ${s} ?`,g,pickN(others,3),{expl:`${g.charAt(0).toUpperCase()+g.slice(1)} touche l’objet : action de contact. La Terre, elle, agit à distance.`,hint:'Qui le touche ?'});}
    return ch(`Quelle action à distance s’exerce toujours sur ${s} ?`,'celle de la Terre (pesanteur)',['celle de l’air','aucune','celle du Soleil uniquement'],{expl:'Sur Terre, tout objet est attiré par la Terre, même sans contact : c’est la pesanteur.',hint:'Pourquoi les objets tombent-ils ?'});},5],
  [sort({'action de contact':['le pied qui frappe un ballon','le sol qui soutient une chaise','l’eau qui porte un bateau','la corde qui tire une luge','le vent qui pousse une voile','la main qui comprime un ressort'],'action à distance':['la Terre qui attire un parachutiste','un aimant qui attire une bille d’acier sans la toucher','une règle frottée qui attire des petits bouts de papier','le Soleil qui attire la Terre']},{q:'« %s » : de quel type d’action s’agit-il ?',e:(x,c)=>`« ${x} » : ${c}.`}),2],
  [bank([['Dans un diagramme objet-interaction, une interaction à distance est représentée par…','un trait en pointillés',['un trait plein','une flèche rouge','un cercle'],'Trait plein : contact ; pointillés : à distance.'],
   ['Un ballon posé au sol est immobile. On peut dire que…','les actions du sol et de la Terre se compensent',['aucune action ne s’exerce sur lui','seule la Terre agit','seul le sol agit'],'Il est attiré par la Terre et soutenu par le sol.',2],
   ['La Terre attire une pomme. La pomme attire-t-elle la Terre ?','oui, c’est une interaction',['non, jamais','seulement si elle tombe','seulement la nuit'],'Toute action est réciproque ; l’effet sur la Terre, énorme, est imperceptible.',3],
   ['Quel est l’effet d’une raquette sur une balle qui arrive vers elle ?','elle modifie la valeur et la direction de sa vitesse',['elle ne fait rien','elle arrête la Terre','elle change la masse de la balle'],'La balle repart dans une autre direction, à une autre vitesse.',2],
   ['Au cycle 4, une action mécanique sera modélisée par une force, dont l’unité est…','le newton (N)',['le kilogramme (kg)','le joule (J)','le watt (W)'],'La force se mesure avec un dynamomètre, en newtons.',3]]),2])},

{id:'pc5g',name:'Énergie et conversions',icon:'⚡',domain:'Énergie',
 refs:[REF5,T5('thème « L’énergie, ses transferts et ses conversions » ; repères : en 5e, retour sur les sources et conversions, comparaison d’ordres de grandeur d’énergies ou de puissances')],
 tip:'Énergie reçue = énergie utile + énergie perdue : ce qui entre dans un convertisseur ressort toujours, mais pas forcément sous la forme souhaitée.',
 c:C(`Une bouilloire, un sèche-cheveux, une lampe à DEL : sur chaque appareil est inscrite une <b>puissance</b> en watts. Que signifie ce nombre ? Et où passe l’énergie qu’un appareil reçoit ? Rien ne se perd : elle se convertit.`,
  [T('Sources, formes, conversions',`<p>Les <b>sources</b> (ou ressources) d’énergie sont renouvelables (Soleil, vent, eau, biomasse, géothermie) ou non (pétrole, gaz, charbon, uranium). Les <b>formes</b> d’énergie : cinétique, de position (pesanteur), thermique, chimique, nucléaire, électrique, lumineuse.</p><p>Un <b>convertisseur</b> change la forme de l’énergie. On le représente par une <b>chaîne énergétique</b>. L’énergie se <b>conserve</b> : <b>énergie reçue = énergie utile + énergie perdue</b> (souvent sous forme thermique). L’unité d’énergie est le <b>joule (J)</b>.</p>`),
   T('Puissance : comparer des appareils',`<p>La <b>puissance</b>, en <b>watts (W)</b>, indique la quantité d’énergie convertie chaque seconde : plus elle est grande, plus l’appareil convertit d’énergie en une même durée. 1 kW = 1 000 W.</p><table class="ptable"><tr><th>Appareil</th><th>Puissance (ordre de grandeur)</th></tr><tr><td>lampe à DEL</td><td>5 à 10 W</td></tr><tr><td>chargeur de téléphone</td><td>10 à 20 W</td></tr><tr><td>téléviseur</td><td>100 W</td></tr><tr><td>réfrigérateur</td><td>150 W</td></tr><tr><td>sèche-cheveux</td><td>2 000 W</td></tr><tr><td>bouilloire</td><td>2 000 W</td></tr></table><p>Une lampe à DEL éclaire autant qu’une lampe à incandescence de 60 W en recevant environ 8 fois moins d’énergie : elle perd moins d’énergie thermique.</p>`)],
  [{q:'Une lampe reçoit 100 J d’énergie électrique et fournit 15 J d’énergie lumineuse. Que devient le reste ?',s:['L’énergie se conserve : énergie reçue = énergie utile + énergie perdue.','Énergie perdue = 100 − 15 = 85 J.','Ces 85 J sont perdus sous forme thermique : la lampe chauffe.']}],
  ['Je repère la forme d’énergie reçue et la forme utile fournie.','Je trace la chaîne énergétique : réservoir → convertisseur → énergie utile + énergie perdue.','J’applique la conservation : énergie perdue = énergie reçue − énergie utile.','Pour comparer des appareils, je convertis leurs puissances dans la même unité (W).'],
  ['Dire que l’énergie est « détruite » ou « consommée » : elle est convertie en d’autres formes.','Confondre puissance (W) et énergie (J).','Oublier que 1 kW = 1 000 W en comparant des appareils.'],
  ['L’énergie se conserve : reçue = utile + perdue.','La puissance (W) mesure l’énergie convertie par seconde ; 1 kW = 1 000 W.','Sources renouvelables : Soleil, vent, eau, biomasse ; non renouvelables : pétrole, gaz, charbon, uranium.']),
 g:mix([d=>{const D=[['une lampe','électrique','lumineuse','thermique'],['un moteur électrique','électrique','cinétique','thermique'],['un panneau photovoltaïque','lumineuse','électrique','thermique'],['un moteur de voiture à essence','chimique','cinétique','thermique'],['une éolienne','cinétique','électrique','thermique'],['un téléviseur','électrique','lumineuse et sonore','thermique']];const [n,i,u,p]=P(D);
    const Ein=d===1?P([100,200,500,1000]):R(10,99)*10;const Eu=d===1?Ein/P([2,4,5,10]):rd(Ein*R(5,60)/100);const Ep=rd(Ein-Eu);
    if(Math.random()<.6)return num(`${n.charAt(0).toUpperCase()+n.slice(1)} reçoit <b>${nf(Ein)} J</b> d’énergie ${i} et fournit <b>${F(Eu)} J</b> d’énergie ${u}. Quelle énergie est perdue (sous forme ${p}) ?`,Ep,{unit:'J',expl:`Conservation de l’énergie : perdue = reçue − utile = ${nf(Ein)} − ${F(Eu)} = <b>${F(Ep)} J</b>.`,hint:'L’énergie se conserve.'});
    return num(`${n.charAt(0).toUpperCase()+n.slice(1)} fournit <b>${F(Eu)} J</b> d’énergie ${u} et perd <b>${F(Ep)} J</b> sous forme ${p}. Quelle énergie ${i} a-t-il (ou elle) reçue ?`,Ein,{unit:'J',expl:`Reçue = utile + perdue = ${F(Eu)} + ${F(Ep)} = <b>${nf(Ein)} J</b>.`,hint:'Reçue = utile + perdue.'});},3],
  [d=>{const kw=d===1?R(1,5):P([R(1,30)/10,R(11,99)/10,R(1,9)]);const w=rd(kw*1000);
    if(Math.random()<.5)return num(`Une bouilloire ou un radiateur a une puissance de <b>${F(kw)} kW</b>. Exprime-la en watts.`,w,{unit:'W',expl:`1 kW = 1 000 W : ${F(kw)} × 1 000 = <b>${nf(w)} W</b>.`,hint:'1 kW = 1 000 W.'});
    return num(`Un four a une puissance de <b>${nf(w)} W</b>. Exprime-la en kW.`,kw,{unit:'kW',expl:`1 kW = 1 000 W : ${nf(w)} ÷ 1 000 = <b>${F(kw)} kW</b>.`,hint:'Divise par 1 000.'});},2],
  [d=>{const A=[['une lampe à DEL',8],['un chargeur de téléphone',15],['un téléviseur',100],['un réfrigérateur',150],['un ordinateur portable',50],['un sèche-cheveux',2000],['une bouilloire électrique',2200],['un four électrique',3000]];
    let s;for(let k=0;k<20;k++){s=pickN(A,3);const v=s.map(x=>x[1]).sort((a,b)=>a-b);if(v[1]>=v[0]*2&&v[2]>=v[1]*2)break;}
    const sorted=s.slice().sort((a,b)=>a[1]-b[1]);if(d>=2&&Math.random()<.5)return order('Range ces appareils du moins puissant au plus puissant (ordres de grandeur) :',sorted.map(x=>x[0]),{expl:sorted.map(x=>`${x[0]} (≈ ${nf(x[1])} W)`).join(' &lt; ')});
    const top=sorted[2];return ch(`Lequel de ces appareils a la plus grande puissance ?`,top[0],sorted.slice(0,2).map(x=>x[0]),{expl:`Ordres de grandeur : ${sorted.map(x=>`${x[0]} ≈ ${nf(x[1])} W`).join(' ; ')}. Les appareils qui chauffent sont les plus puissants.`,hint:'Les appareils chauffants sont très puissants.'});},2],
  [sort({'renouvelable':['le Soleil','le vent','l’eau des barrages','la biomasse (bois, déchets végétaux)','la géothermie'],'non renouvelable':['le pétrole','le gaz naturel','le charbon','l’uranium']},{q:'La ressource « %s » est…',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} : ressource ${c} à l’échelle humaine.`}),2],
  [bank([['Quelle est l’unité d’énergie ?','le joule (J)',['le watt (W)','le volt (V)','le newton (N)'],'Le watt est l’unité de puissance.'],
   ['La puissance d’un appareil indique…','l’énergie qu’il convertit chaque seconde',['sa masse','sa taille','la durée de son utilisation'],'1 W = 1 J par seconde.',2],
   ['Une lampe à DEL éclaire autant qu’une lampe à incandescence de 60 W avec environ…','8 W',['60 W','600 W','0,1 W'],'Elle perd beaucoup moins d’énergie thermique.',2],
   ['« Consommer de l’énergie » signifie en réalité…','convertir de l’énergie d’une forme en une autre',['détruire de l’énergie','créer de l’énergie','stocker de l’énergie'],'L’énergie se conserve : elle change de forme.',3],
   ['Dans une centrale thermique au gaz, la combustion émet…','du dioxyde de carbone',['de l’uranium','du dioxygène pur','rien du tout'],'Les combustibles fossiles rejettent du CO₂, gaz à effet de serre.',2],
   {o:['énergie chimique (essence)','moteur','énergie cinétique (et thermique perdue)'],q:'Remets dans l’ordre la chaîne énergétique d’une voiture à essence :',e:'Réservoir d’énergie chimique → convertisseur (moteur) → énergie utile cinétique + énergie thermique perdue.',d:2}]),2])},

{id:'pc5h',name:'Circuits électriques : série et dérivation',icon:'🔌',domain:'Électricité',
 refs:[REF5,T5('thème « L’énergie, ses transferts et ses conversions » : « Réaliser des circuits électriques simples » (dipôles en série, dipôles en dérivation) ; repères : propriétés du courant abordées qualitativement dès la 5e')],
 tip:'Compte les boucles : une seule boucle, tout est en série (un élément coupé éteint tout) ; plusieurs boucles, chaque branche en dérivation fonctionne indépendamment.',
 c:C(`Dans une guirlande ancienne, une seule ampoule grillée éteignait tout ; chez toi, quand une lampe grille, les autres restent allumées. Pourquoi ? Parce que les lampes ne sont pas branchées de la même façon : <b>en série</b> ou <b>en dérivation</b>.`,
  [T('Le circuit en série',`<p>Dans un circuit <b>en série</b>, tous les dipôles forment <b>une seule boucle</b>. Le courant traverse chaque dipôle l’un après l’autre ; il a la <b>même intensité en tout point</b> du circuit. Conséquences :</p><ul class="lst"><li>si un dipôle est retiré ou grillé, la boucle est ouverte : <b>plus rien ne fonctionne</b> ;</li><li>plus on ajoute de lampes en série, <b>moins elles brillent</b> ;</li><li>l’ordre des dipôles n’a pas d’importance.</li></ul>`),
   T('Le circuit en dérivation',`<p>Dans un circuit <b>en dérivation</b>, il y a <b>plusieurs boucles</b> : chaque lampe est dans sa propre <b>branche</b>, reliée aux bornes de la pile par des <b>nœuds</b>. Conséquences :</p><ul class="lst"><li>si une lampe est dévissée, <b>les autres continuent de briller</b> ;</li><li>un interrupteur placé dans une branche ne commande que cette branche ; dans la <b>branche principale</b>, il commande tout ;</li><li>chaque lampe brille normalement, comme si elle était seule. Les installations domestiques sont en dérivation.</li></ul>`),
   T('Court-circuit',`<p>Un fil reliant les deux bornes d’une lampe en série la <b>court-circuite</b> : elle s’éteint et les autres lampes de la boucle brillent davantage. Court-circuiter le <b>générateur</b> (ou une lampe en dérivation directement aux bornes de la pile) est <b>dangereux</b> : le courant devient très intense, les fils et la pile chauffent, risque d’incendie. Les fusibles et disjoncteurs protègent les installations.</p>`)],
  [{q:'L1 est dans la branche principale ; L2 et L3 sont en dérivation. On dévisse L2. Que se passe-t-il ?',s:['L2 dévissée : sa branche est ouverte, L2 s’éteint.','La branche de L3 forme toujours une boucle fermée avec L1 et la pile.','L1 et L3 restent allumées.']}],
  ['Je compte les boucles : une seule (série) ou plusieurs (dérivation).','Je repère la branche principale et les branches dérivées.','Pour chaque lampe, je cherche s’il existe encore une boucle fermée passant par elle et par la pile.','Je vérifie qu’il n’y a pas de court-circuit dangereux.'],
  ['Croire qu’en série la première lampe « prend » le courant et brille plus que les autres.','Penser qu’un interrupteur dans une branche dérivée éteint toutes les lampes.','Croire qu’un court-circuit de la pile est sans danger parce qu’on n’utilise qu’une pile.'],
  ['Série : une boucle, même courant partout ; un élément coupé, tout s’arrête.','Dérivation : plusieurs boucles ; chaque branche fonctionne indépendamment.','Un court-circuit du générateur est dangereux.']),
 g:mix([d=>{const L=(n)=>({t:'L',n});const K=(n,o=false)=>({t:'K',n,o});const S=(...x)=>({t:'S',x});const Pa=(...x)=>({t:'P',x});
    const TOP=[
     {desc:'La pile, l’interrupteur K (fermé) et les lampes L1 et L2 sont tous en série, dans une seule boucle.',c:S(K('K'),L('L1'),L('L2')),lamps:['L1','L2']},
     {desc:'La pile, l’interrupteur K (fermé) et les lampes L1, L2 et L3 sont tous en série, dans une seule boucle.',c:S(K('K'),L('L1'),L('L2'),L('L3')),lamps:['L1','L2','L3']},
     {desc:'Les lampes L1 et L2 sont en dérivation aux bornes de la pile, chacune dans sa branche ; l’interrupteur K (fermé) est dans la branche principale.',c:S(K('K'),Pa(S(L('L1')),S(L('L2')))),lamps:['L1','L2']},
     {desc:'Les lampes L1, L2 et L3 sont en dérivation aux bornes de la pile, chacune dans sa branche ; l’interrupteur K (fermé) est dans la branche principale.',c:S(K('K'),Pa(S(L('L1')),S(L('L2')),S(L('L3')))),lamps:['L1','L2','L3']},
     {desc:'L1 et L2 sont en dérivation ; l’interrupteur K1 (fermé) est dans la branche de L1 et K2 (fermé) dans celle de L2.',c:S(Pa(S(K('K1'),L('L1')),S(K('K2'),L('L2')))),lamps:['L1','L2']},
     {desc:'L1 est dans la branche principale, en série avec la pile et l’interrupteur K (fermé) ; L2 et L3 sont en dérivation, chacune dans sa branche.',c:S(K('K'),L('L1'),Pa(S(L('L2')),S(L('L3')))),lamps:['L1','L2','L3']},
     {desc:'L1 et L2 sont en série dans une même branche ; L3 est seule dans une autre branche, en dérivation ; l’interrupteur K (fermé) est dans la branche principale.',c:S(K('K'),Pa(S(L('L1'),L('L2')),S(L('L3')))),lamps:['L1','L2','L3']}];
    const tp=d===1?P(TOP.slice(0,4)):P(TOP);const items=[];const walk=e=>{if(e.t==='L'||e.t==='K')items.push(e);else e.x.forEach(walk);};walk(tp.c);
    const act=P(items);const actTxt=act.t==='L'?`On dévisse la lampe ${act.n}.`:`On ouvre l’interrupteur ${act.n}.`;const off=new Set([act.n]);
    const cond=e=>e.t==='L'||e.t==='K'?!off.has(e.n):e.t==='S'?e.x.every(cond):e.x.some(cond);
    const lit=new Set();const mark=(e,ok)=>{if(e.t==='L'){if(ok&&!off.has(e.n))lit.add(e.n);}else if(e.t==='K'){}else if(e.t==='S'){const o=ok&&e.x.every(cond);e.x.forEach(y=>mark(y,o));}else e.x.forEach(y=>mark(y,ok&&cond(y)));};
    mark(tp.c,true);const label=s=>{const a=tp.lamps.filter(x=>s.has(x));return !a.length?'aucune lampe ne brille':a.length===tp.lamps.length?'toutes les lampes brillent':a.length===1?`seule ${a[0]} brille`:`${a.slice(0,-1).join(', ')} et ${a[a.length-1]} brillent`;};
    const good=label(lit);const subs=[];const n=tp.lamps.length;for(let m=0;m<(1<<n);m++){const s=new Set(tp.lamps.filter((x,i)=>m>>i&1));subs.push(label(s));}
    const ser=tp.c.x.every(e=>e.t!=='P');
    return ch(`${tp.desc} ${actTxt} Quelles lampes brillent encore ?`,good,shuffle(subs.filter(x=>x!==good)),{expl:`${ser?'Circuit en série : une seule boucle ; ouvrir la boucle n’importe où éteint tout.':'Une lampe brille s’il existe encore une boucle fermée passant par elle et par la pile.'} Après l’action : <b>${good}</b>.`,hint:'Suis chaque boucle depuis la pile.'});},6],
  [bank([['Dans un circuit en série, une lampe grille. Les autres lampes…','s’éteignent',['continuent de briller','brillent plus fort','brillent moins fort'],'La boucle unique est ouverte : le courant ne circule plus.'],
   ['Dans une maison, les lampes et les prises sont branchées…','en dérivation',['en série','en court-circuit','sans fil'],'Chaque appareil fonctionne indépendamment des autres.'],
   ['On ajoute une troisième lampe en série avec deux autres. Les lampes…','brillent moins',['brillent plus','brillent autant','s’éteignent toutes'],'Plus il y a de lampes en série, plus le courant est faible.',2],
   ['Dans un circuit en série, l’intensité du courant est…','la même en tout point',['plus grande près de la borne +','plus faible après chaque lampe','nulle entre deux lampes'],'Le courant ne s’use pas : il est le même partout dans une boucle unique.',2],
   ['On relie par un fil les deux bornes de L1, en série avec L2. Que se passe-t-il ?','L1 s’éteint et L2 brille davantage',['les deux lampes s’éteignent','L1 brille plus fort','rien ne change'],'L1 est court-circuitée : le courant passe par le fil ; L2 reçoit plus de courant.',3],
   ['Pourquoi est-il dangereux de relier directement les bornes de la pile par un fil ?','le courant devient très intense : la pile et le fil chauffent',['la pile se recharge trop','le fil devient isolant','la lumière devient trop forte'],'C’est un court-circuit du générateur : risque d’échauffement et d’incendie.',2],
   ['Un nœud dans un circuit est…','un point relié à au moins trois fils',['un fil emmêlé','une lampe grillée','un interrupteur ouvert'],'Les nœuds délimitent les branches d’un circuit en dérivation.',2],
   ['Un interrupteur placé dans une branche dérivée commande…','seulement la lampe de sa branche',['toutes les lampes','aucune lampe','la pile'],'Les autres branches forment encore des boucles fermées.',2]]),3])},

{id:'pc5i',name:'Lumière : sources, propagation et vision',icon:'👁️',domain:'Signaux',
 refs:[REF5,T5('thème « Des signaux pour observer et communiquer » : signaux lumineux (source primaire et objet diffusant, propagation rectiligne, modèle du rayon lumineux, vitesse de propagation, année-lumière)')],
 tip:'Pour voir un objet, il faut que de la lumière parte de lui et entre dans ton œil : dessine toujours la flèche de la lumière vers l’œil, jamais de l’œil vers l’objet.',
 c:C(`La Lune brille-t-elle par elle-même ? Comment voit-on une feuille blanche dans une pièce éclairée, mais pas dans le noir complet ? Pour comprendre la <b>vision</b>, il faut savoir d’où vient la lumière et comment elle voyage.`,
  [T('Sources primaires et objets diffusants',`<p>Une <b>source primaire</b> produit la lumière qu’elle émet : le Soleil, les étoiles, une flamme, une lampe allumée, un écran allumé, une luciole. Un <b>objet diffusant</b> ne produit pas de lumière : il renvoie dans toutes les directions une partie de la lumière qu’il reçoit (la Lune, les planètes, un mur, une feuille de papier, toi).</p><p>On voit un objet si de la lumière issue de cet objet <b>entre dans l’œil</b>. Dans le noir complet, un objet diffusant est invisible.</p>`),
   T('Propagation de la lumière',`<p>Dans un milieu transparent et homogène (vide, air, eau), la lumière se propage <b>en ligne droite</b>. On la représente par un <b>rayon lumineux</b> : une droite fléchée dans le sens de propagation. Ce modèle explique les ombres et l’alignement d’une visée.</p><p>Vitesse de la lumière dans le vide (et presque dans l’air) : environ <b>300 000 km/s</b>. Elle met environ 1,3 s pour venir de la Lune (384 000 km) et environ 500 s, soit 8 min 20 s, pour venir du Soleil (150 millions de km). Une <b>année-lumière</b> (al) est la <b>distance</b> parcourue par la lumière en un an : environ 9 460 milliards de km. Ne regarde jamais le Soleil ni un faisceau laser directement.</p>`)],
  [{q:'Combien de temps la lumière met-elle pour parcourir les 384 000 km entre la Lune et la Terre ?',s:['t = d ÷ v, avec v = 300 000 km/s.','t = 384 000 ÷ 300 000.','t = 1,28 s : on voit la Lune telle qu’elle était il y a environ 1,3 s.']}],
  ['Je repère la source primaire et les objets diffusants.','Je trace le trajet de la lumière : source → objet → œil, en lignes droites fléchées.','Pour une durée ou une distance, j’utilise d = v × t avec v = 300 000 km/s (unités : km et s).','Je pense à la sécurité : pas d’observation directe du Soleil ou d’un laser.'],
  ['Croire que la Lune est une source de lumière : elle diffuse la lumière du Soleil.','Dessiner des rayons qui partent de l’œil vers l’objet.','Prendre l’année-lumière pour une durée : c’est une distance.'],
  ['Source primaire : produit sa lumière ; objet diffusant : renvoie la lumière reçue.','La lumière se propage en ligne droite, à environ 300 000 km/s ; on la modélise par des rayons.','On voit un objet quand sa lumière entre dans l’œil ; l’année-lumière est une distance.']),
 g:mix([sort({'source primaire de lumière':['le Soleil','une flamme de bougie','une lampe allumée','l’écran allumé d’une tablette','une étoile','une luciole'],'objet diffusant':['la Lune','la planète Vénus','une feuille de papier','un mur blanc','un nuage','ton visage']},{q:'« %s » : source primaire ou objet diffusant ?',e:(x,c)=>`${x.charAt(0).toUpperCase()+x.slice(1)} : ${c}${c==='objet diffusant'?' (il renvoie la lumière qu’il reçoit)':' (il produit sa propre lumière)'}.`}),3],
  [d=>{const r=Math.random();
    if(r<.4){const t=P([0.5,1,1.5,2,2.5,3,4,5,10,20]);const D=rd(300000*t);return num(`La lumière se propage à environ 300 000 km/s. Quelle distance parcourt-elle en <b>${F(t)} s</b> ?`,D,{unit:'km',expl:`d = v × t = 300 000 × ${F(t)} = <b>${nf(D)} km</b>.`,hint:'d = v × t.'});}
    if(r<.75){const X=P([[384000,'de la Lune à la Terre'],[150000000,'du Soleil à la Terre'],[108000000,'du Soleil à Vénus'],[228000000,'du Soleil à Mars'],[778000000,'du Soleil à Jupiter'],[36000,'d’un satellite géostationnaire à la Terre']]);const t=rd(X[0]/300000);
      return num(`La lumière va à environ 300 000 km/s. Combien de secondes met-elle pour parcourir les <b>${nf(X[0])} km</b> ${X[1]} ?`,t,{unit:'s',expl:`t = d ÷ v = ${nf(X[0])} ÷ 300 000 = <b>${F(t)} s</b>${t>=60?` (environ ${Math.floor(t/60)} min ${Math.round(t%60)} s)`:''}.`,hint:'t = d ÷ v, avec d en km et v en km/s.'});}
    const t=P([1,2,3,5,8]);return ch(`Une sonde envoie un signal lumineux (ou radio, même vitesse : 300 000 km/s) qui met <b>${t} min</b> à nous parvenir. À quelle distance est-elle ?`,`${nf(300000*60*t)} km`,[`${nf(300000*t)} km`,`${nf(300*60*t)} km`,`${nf(340*60*t)} km`],{expl:`${t} min = ${60*t} s ; d = 300 000 × ${60*t} = <b>${nf(300000*60*t)} km</b>.`,hint:'Convertis d’abord les minutes en secondes.'});},4],
  [bank([['La Lune éclaire la nuit parce que…','elle diffuse la lumière qu’elle reçoit du Soleil',['elle produit sa propre lumière','elle est en feu','elle reflète la lumière de la Terre uniquement'],'La Lune est un objet diffusant, pas une source primaire.'],
   ['Pour voir une feuille de papier, il faut que…','de la lumière venant de la feuille entre dans l’œil',['l’œil envoie des rayons vers la feuille','la feuille soit une source primaire','la pièce soit dans le noir'],'La feuille diffuse la lumière de la lampe ; une partie arrive dans l’œil.'],
   ['L’année-lumière est une unité de…','distance',['durée','vitesse','luminosité'],'C’est la distance parcourue par la lumière en un an (environ 9 460 milliards de km).',2],
   ['Dans un milieu transparent et homogène, la lumière se propage…','en ligne droite',['en zigzag','en cercle','seulement vers le bas'],'C’est la propagation rectiligne, modélisée par le rayon lumineux.'],
   ['On voit le Soleil tel qu’il était il y a environ…','8 minutes',['8 secondes','8 heures','8 jours'],'150 000 000 km ÷ 300 000 km/s = 500 s ≈ 8 min 20 s.',2],
   ['Pourquoi ne faut-il jamais viser l’œil de quelqu’un avec un pointeur laser ?','la lumière concentrée peut brûler la rétine',['le laser est trop lent','la lumière laser est invisible','cela abîme seulement le laser'],'Les lasers peuvent provoquer des lésions définitives de l’œil.',2],
   ['L’étoile la plus proche après le Soleil, Proxima du Centaure, est à environ 4,2 années-lumière. Sa lumière a donc voyagé pendant environ…','4,2 ans',['4,2 jours','4,2 secondes','420 ans'],'Par définition de l’année-lumière : 4,2 al ↔ 4,2 ans de voyage.',3]]),2])},

{id:'pc5j',name:'Son et fréquence',icon:'🎵',domain:'Signaux',
 refs:[REF5,T5('thème « Des signaux pour observer et communiquer » : signaux sonores (conditions de propagation, vitesse de propagation, notion de fréquence : sons audibles, infrasons, ultrasons) ; repère : maîtrise de la fréquence en fin de cycle')],
 tip:'Fréquence = nombre de vibrations par seconde (Hz). Plus elle est grande, plus le son est aigu ; l’oreille humaine entend de 20 Hz à 20 000 Hz.',
 c:C(`Une chauve-souris chasse dans le noir grâce à des sons que nous n’entendons pas. Les éléphants communiquent avec des sons trop graves pour nous. Qu’est-ce qui distingue un son grave d’un son aigu, et jusqu’où porte l’oreille humaine ? La réponse tient en un mot : la <b>fréquence</b>.`,
  [T('Propagation du son',`<p>Un son est produit par une <b>vibration</b> et se propage de proche en proche dans un milieu matériel. Il ne se propage pas dans le vide. Sa vitesse dépend du milieu : environ <b>340 m/s dans l’air</b>, environ 1 500 m/s dans l’eau, encore plus dans les solides comme l’acier. On utilise <b>d = v × t</b> : orage, écho, sonar (aller-retour : on divise la distance parcourue par 2).</p>`),
   T('La fréquence',`<p>La <b>fréquence</b> f d’un son est le nombre de vibrations par seconde. Unité : le <b>hertz (Hz)</b> ; 1 kHz = 1 000 Hz. Une corde qui fait 440 vibrations en 1 s émet un son de 440 Hz (le la du diapason). Si l’on compte N vibrations en t secondes : <b>f = N ÷ t</b>.</p><p>Plus la fréquence est <b>élevée</b>, plus le son est <b>aigu</b> ; plus elle est basse, plus il est <b>grave</b>.</p><table class="ptable"><tr><th>Domaine</th><th>Fréquence</th><th>Exemples</th></tr><tr><td>infrasons</td><td>moins de 20 Hz</td><td>éléphants, séismes</td></tr><tr><td>sons audibles (humain)</td><td>de 20 Hz à 20 000 Hz</td><td>voix, musique</td></tr><tr><td>ultrasons</td><td>plus de 20 000 Hz</td><td>chauves-souris, dauphins, échographie</td></tr></table>`),
   T('Intensité sonore et santé',`<p>Le <b>niveau d’intensité sonore</b> se mesure avec un sonomètre, en <b>décibels (dB)</b>. Un son est d’autant plus fort que son niveau est élevé. À partir d’environ <b>85 dB</b>, une exposition prolongée est dangereuse pour l’audition ; vers <b>120 dB</b>, le son devient douloureux. Les dégâts de l’oreille interne sont irréversibles : on se protège (bouchons, volume modéré, pauses).</p>`)],
  [{q:'Une corde fait 1 320 vibrations en 3 s. Quelle est la fréquence du son ? Est-il audible ?',s:['f = N ÷ t = 1 320 ÷ 3.','f = 440 Hz.','440 Hz est compris entre 20 Hz et 20 000 Hz : le son est audible (c’est le la du diapason).']},
   {q:'Un sonar envoie des ultrasons vers le fond de la mer ; l’écho revient 0,4 s plus tard. Profondeur ? (v = 1 500 m/s)',s:['Distance aller-retour : d = 1 500 × 0,4 = 600 m.','Le son fait l’aller et le retour : on divise par 2.','Profondeur : 300 m.']}],
  ['Je calcule la fréquence : f = nombre de vibrations ÷ durée (en s).','Je compare à 20 Hz et à 20 000 Hz pour classer le son.','Pour une distance, d = v × t, en divisant par 2 s’il y a un aller-retour (écho).','Je relie fréquence et hauteur : aigu = fréquence élevée.'],
  ['Confondre fréquence (aigu ou grave) et intensité (fort ou faible).','Oublier de diviser par 2 dans un calcul d’écho.','Croire que les ultrasons sont des sons très forts : ce sont des sons très aigus, que nous n’entendons pas.'],
  ['Fréquence = nombre de vibrations par seconde, en hertz (Hz).','Audible : 20 Hz à 20 000 Hz ; en dessous, infrasons ; au-dessus, ultrasons.','Son dans l’air ≈ 340 m/s ; niveau sonore en dB, danger à partir d’environ 85 dB.']),
 g:mix([d=>{const f=P([P([2,5,8,10,15]),R(30,19000),R(25,15000),P([25000,30000,40000,50000,80000,100000])]);
    const dom=f<20?'infrason':f<=20000?'son audible':'ultrason';return ch(`Un son a une fréquence de <b>${nf(f)} Hz</b>. Pour l’oreille humaine, c’est…`,dom==='infrason'?'un infrason (inaudible)':dom==='son audible'?'un son audible':'un ultrason (inaudible)',['un infrason (inaudible)','un son audible','un ultrason (inaudible)'],{expl:`L’oreille humaine entend de 20 Hz à 20 000 Hz. ${nf(f)} Hz ${f<20?'< 20 Hz : infrason':f<=20000?'est dans cet intervalle : audible':'> 20 000 Hz : ultrason'}.`,hint:'Compare à 20 Hz et 20 000 Hz.'});},3],
  [d=>{const f=P(d===1?[100,200,250,440,500]:[50,110,262,330,440,523,880,1000,2000]);const t=P(d===1?[1,2]:[2,3,4,5,0.5]);const N=rd(f*t);
    return num(`Une source vibre <b>${nf(N)} fois</b> en <b>${F(t)} s</b>. Quelle est la fréquence du son émis ?`,f,{unit:'Hz',expl:`f = N ÷ t = ${nf(N)} ÷ ${F(t)} = <b>${nf(f)} Hz</b>.`,hint:'Nombre de vibrations par seconde.'});},3],
  [d=>{const a=R(100,4000),b=R(100,4000);if(Math.abs(a-b)<50)return thunder(d);const hi=a>b?'A':'B';
    return ch(`Le son A a une fréquence de ${nf(a)} Hz, le son B de ${nf(b)} Hz. Lequel est le plus aigu ?`,`le son ${hi}`,[`le son ${hi==='A'?'B':'A'}`,'ils sont aussi aigus l’un que l’autre','le plus fort des deux'],{expl:`Plus la fréquence est élevée, plus le son est aigu : ${nf(Math.max(a,b))} Hz > ${nf(Math.min(a,b))} Hz, donc <b>le son ${hi}</b>.`,hint:'Aigu = fréquence élevée.'});},2],
  [d=>{const r=Math.random();if(r<.4)return thunder(d);
    if(r<.7){const t=P([1,2,3,4,0.5,1.5]);const D=rd(340*t/2);return num(`Face à une falaise, tu cries et tu entends l’écho <b>${F(t)} s</b> plus tard. Le son va à 340 m/s dans l’air. À quelle distance est la falaise ?`,D,{unit:'m',expl:`Le son fait l’aller-retour : 340 × ${F(t)} = ${F(rd(340*t))} m, puis ÷ 2 = <b>${F(D)} m</b>.`,hint:'Aller-retour : divise par 2.'});}
    const t=P([0.2,0.4,0.6,0.8,1,1.2,2]);const D=rd(1500*t/2);return num(`Un sonar envoie des ultrasons vers le fond ; l’écho revient <b>${F(t)} s</b> plus tard. Dans l’eau, v = 1 500 m/s. Quelle est la profondeur ?`,D,{unit:'m',expl:`Aller-retour : 1 500 × ${F(t)} = ${F(rd(1500*t))} m ; profondeur = ${F(rd(1500*t))} ÷ 2 = <b>${F(D)} m</b>.`,hint:'Aller-retour : divise par 2.'});},3],
  [bank([['Un son de fréquence élevée est…','aigu',['grave','fort','lent'],'La hauteur d’un son dépend de sa fréquence.'],
   ['Quelle est l’unité de fréquence ?','le hertz (Hz)',['le décibel (dB)','le mètre par seconde (m/s)','le watt (W)'],'Le décibel mesure le niveau d’intensité sonore.'],
   ['Les chauves-souris se repèrent grâce…','aux ultrasons',['aux infrasons','à la lumière','aux ondes radio'],'Elles émettent des sons très aigus (plus de 20 000 Hz) et écoutent leur écho.'],
   ['Un son de 90 dB…','est fort : une exposition prolongée peut abîmer l’audition',['est très grave','est inaudible','est un ultrason'],'Le niveau en dB mesure l’intensité ; danger à partir d’environ 85 dB.',2],
   ['Le son se propage plus vite…','dans l’eau que dans l’air',['dans l’air que dans l’eau','dans le vide','à la même vitesse partout'],'Environ 1 500 m/s dans l’eau contre 340 m/s dans l’air.',2],
   ['Avec l’âge, l’oreille humaine entend moins bien…','les sons très aigus',['les sons très graves','les sons forts','tous les sons de la même façon'],'La limite haute (20 000 Hz chez l’enfant) baisse avec l’âge.',3],
   ['Augmenter le volume d’une enceinte modifie…','le niveau d’intensité sonore (dB), pas la fréquence',['la fréquence','la vitesse du son','la hauteur de la note'],'Fort/faible et aigu/grave sont deux caractéristiques différentes.',3]]),2])}
]);

/* Volume à partir de m et ρ (version simple) utilisée en difficulté 1-2 de pc5c. */
function vrho(d){const [n,rho]=P(LIQ.slice(1,3));const V=P([100,200,250,500,1000]);const m=rd(rho*V);
  return ch(`Quelle est la masse de ${V} mL ${de(n)} ?`,`${F(m)} g`,[`${F(rd(V/rho,2))} g`,`${F(rd(m*10))} g`,`${F(rd(V+rho))} g`],{expl:`ρ(${n}) = ${F(rho)} g/mL ; m = ρ × V = ${F(rho)} × ${V} = <b>${F(m)} g</b>.`,hint:'m = ρ × V.'});}
})();
